  '1;1;0;\nT;0;2:17:1:مَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارࣰا فَلَمَّآ أَضَآءَتۡ مَا حَوۡلَهُۥ\nT;0;2:17:2:ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِي ظُلُمَٰتࣲ لَّا يُبۡصِرُونَ¦2:18:1:صُمُّۢ\nT;0;2:18:2:بُكۡمٌ عُمۡيࣱ فَهُمۡ لَا يَرۡجِعُونَ¦2:19:1:أَوۡ كَصَيِّبࣲ مِّنَ ٱلسَّمَآءِ فِيهِ\nT;0;2:19:0:ظُلُمَٰتࣱ وَرَعۡدࣱ وَبَرۡقࣱ يَجۡعَلُونَ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِم مِّنَ\nT;0;2:19:2:ٱلصَّوَٰعِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِيطُۢ بِٱلۡكَٰفِرِينَ¦2:20:1:يَكَادُ ٱلۡبَرۡقُ\nT;0;2:20:0:يَخۡطَفُ أَبۡصَٰرَهُمۡۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوۡاْ فِيهِ وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ\nT;0;2:20:0:قَامُواْۚ وَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ\nT;0;2:20:2:كُلِّ شَيۡءࣲ قَدِيرࣱ¦2:21:1:يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي\nT;0;2:21:2:خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ¦2:22:1:ٱلَّذِي جَعَلَ لَكُمُ\nT;0;2:22:0:ٱلۡأَرۡضَ فِرَٰشࣰا وَٱلسَّمَآءَ بِنَآءࣰ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَخۡرَجَ\nT;0;2:22:0:بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقࣰا لَّكُمۡۖ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادࣰا وَأَنتُمۡ\nT;0;2:22:2:تَعۡلَمُونَ¦2:23:1:وَإِن كُنتُمۡ فِي رَيۡبࣲ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ\nT;0;2:23:0:بِسُورَةࣲ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن\nT;0;2:23:2:كُنتُمۡ صَٰدِقِينَ¦2:24:1:فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ فَٱتَّقُواْ ٱلنَّارَ\nT;0;2:24:2:ٱلَّتِي وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ',
  '1;1;0;2\nT;0;2:25:1:وَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتࣲ\nT;0;2:25:0:تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ كُلَّمَا رُزِقُواْ مِنۡهَا مِن ثَمَرَةࣲ\nT;0;2:25:0:رِّزۡقࣰا قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهࣰاۖ\nT;0;2:25:2:وَلَهُمۡ فِيهَآ أَزۡوَٰجࣱ مُّطَهَّرَةࣱۖ وَهُمۡ فِيهَا خَٰلِدُونَ¦2:26:1:۞ إِنَّ\nT;0;2:26:0:ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلࣰا مَّا بَعُوضَةࣰ فَمَا فَوۡقَهَاۚ فَأَمَّا\nT;0;2:26:0:ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا\nT;0;2:26:0:ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلࣰاۘ\nT;0;2:26:0:يُضِلُّ بِهِۦ كَثِيرࣰا وَيَهۡدِي بِهِۦ كَثِيرࣰاۚ وَمَا يُضِلُّ بِهِۦٓ\nT;0;2:26:2:إِلَّا ٱلۡفَٰسِقِينَ¦2:27:1:ٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ\nT;0;2:27:0:مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ\nT;0;2:27:2:فِي ٱلۡأَرۡضِۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ¦2:28:1:كَيۡفَ\nT;0;2:28:0:تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَٰتࣰا فَأَحۡيَٰكُمۡۖ ثُمَّ يُمِيتُكُمۡ\nT;0;2:28:2:ثُمَّ يُحۡيِيكُمۡ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ¦2:29:1:هُوَ ٱلَّذِي خَلَقَ\nT;0;2:29:0:لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعࣰا ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ\nT;0;2:29:2:فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتࣲۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمࣱ',
  '1;1;1;\nT;0;2:30:1:وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلࣱ فِي ٱلۡأَرۡضِ خَلِيفَةࣰۖ قَالُوٓاْ\nT;0;2:30:0:أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ\nT;0;2:30:2:بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ¦2:31:1:وَعَلَّمَ\nT;0;2:31:0:ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ\nT;0;2:31:2:أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ¦2:32:1:قَالُواْ سُبۡحَٰنَكَ\nT;0;2:32:2:لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ¦2:33:1:قَالَ يَٰٓـَٔادَمُ\nT;0;2:33:0:أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل\nT;0;2:33:0:لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ\nT;0;2:33:2:وَمَا كُنتُمۡ تَكۡتُمُونَ¦2:34:1:وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ\nT;0;2:34:2:فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ¦2:35:1:وَقُلۡنَا\nT;0;2:35:0:يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ\nT;0;2:35:2:شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ¦2:36:1:فَأَزَلَّهُمَا\nT;0;2:36:0:ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ\nT;0;2:36:2:لِبَعۡضٍ عَدُوࣱّۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرࣱّ وَمَتَٰعٌ إِلَىٰ حِينࣲ¦2:37:1:فَتَلَقَّىٰٓ\nT;0;2:37:2:ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتࣲ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ',
  '1;1;1;3\nT;0;2:38:1:قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعࣰاۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدࣰى فَمَن تَبِعَ\nT;0;2:38:2:هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ¦2:39:1:وَٱلَّذِينَ كَفَرُواْ\nT;0;2:39:2:وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ\nT;0;2:40:1:يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَوۡفُواْ بِعَهۡدِيٓ\nT;0;2:40:2:أُوفِ بِعَهۡدِكُمۡ وَإِيَّٰيَ فَٱرۡهَبُونِ¦2:41:1:وَءَامِنُواْ بِمَآ أَنزَلۡتُ مُصَدِّقࣰا\nT;0;2:41:0:لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي\nT;0;2:41:2:ثَمَنࣰا قَلِيلࣰا وَإِيَّٰيَ فَٱتَّقُونِ¦2:42:1:وَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُواْ\nT;0;2:42:2:ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ¦2:43:1:وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ\nT;0;2:43:2:وَٱرۡكَعُواْ مَعَ ٱلرَّٰكِعِينَ¦2:44:1:۞ أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ\nT;0;2:44:2:وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ\nT;0;2:45:3:وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ\nT;0;2:46:3:ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَأَنَّهُمۡ إِلَيۡهِ رَٰجِعُونَ\nT;0;2:47:1:يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ\nT;0;2:47:2:عَلَى ٱلۡعَٰلَمِينَ¦2:48:1:وَٱتَّقُواْ يَوۡمࣰا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسࣲ شَيۡـࣰٔا\nT;0;2:48:2:وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةࣱ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلࣱ وَلَا هُمۡ يُنصَرُونَ',
  '1;1;2;\nT;0;2:49:1:وَإِذۡ نَجَّيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ\nT;0;2:49:0:يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءࣱ\nT;0;2:49:2:مِّن رَّبِّكُمۡ عَظِيمࣱ¦2:50:1:وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَيۡنَٰكُمۡ\nT;0;2:50:2:وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ¦2:51:1:وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ\nT;0;2:51:2:أَرۡبَعِينَ لَيۡلَةࣰ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ\nT;0;2:52:3:ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَٰلِكَ لَعَلَّكُمۡ تَشۡكُرُونَ\nT;0;2:53:3:وَإِذۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ\nT;0;2:54:1:وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ\nT;0;2:54:0:ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ\nT;0;2:54:0:خَيۡرࣱ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ\nT;0;2:54:2:ٱلرَّحِيمُ¦2:55:1:وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ\nT;0;2:55:2:جَهۡرَةࣰ فَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ¦2:56:1:ثُمَّ بَعَثۡنَٰكُم\nT;0;2:56:2:مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ¦2:57:1:وَظَلَّلۡنَا عَلَيۡكُمُ\nT;0;2:57:0:ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ\nT;0;2:57:2:مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ',
  '1;1;2;4\nT;0;2:58:1:وَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ\nT;0;2:58:0:رَغَدࣰا وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدࣰا وَقُولُواْ حِطَّةࣱ نَّغۡفِرۡ لَكُمۡ\nT;0;2:58:2:خَطَٰيَٰكُمۡۚ وَسَنَزِيدُ ٱلۡمُحۡسِنِينَ¦2:59:1:فَبَدَّلَ ٱلَّذِينَ\nT;0;2:59:0:ظَلَمُواْ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ\nT;0;2:59:2:رِجۡزࣰا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ¦2:60:1:۞ وَإِذِ ٱسۡتَسۡقَىٰ\nT;0;2:60:0:مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ\nT;0;2:60:0:مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنࣰاۖ قَدۡ عَلِمَ كُلُّ أُنَاسࣲ مَّشۡرَبَهُمۡۖ كُلُواْ\nT;0;2:60:2:وَٱشۡرَبُواْ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ\nT;0;2:61:1:وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامࣲ وَٰحِدࣲ فَٱدۡعُ لَنَا\nT;0;2:61:0:رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا\nT;0;2:61:0:وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ\nT;0;2:61:0:أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرࣰا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ\nT;0;2:61:0:وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبࣲ مِّنَ\nT;0;2:61:0:ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ\nT;0;2:61:2:ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ',
  '1;1;3;\nT;0;2:62:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنۡ\nT;0;2:62:0:ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحࣰا فَلَهُمۡ أَجۡرُهُمۡ عِندَ\nT;0;2:62:2:رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ¦2:63:1:وَإِذۡ أَخَذۡنَا\nT;0;2:63:0:مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم\nT;0;2:63:2:بِقُوَّةࣲ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ¦2:64:1:ثُمَّ تَوَلَّيۡتُم\nT;0;2:64:0:مِّنۢ بَعۡدِ ذَٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ\nT;0;2:64:2:ٱلۡخَٰسِرِينَ¦2:65:1:وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ\nT;0;2:65:2:فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ¦2:66:1:فَجَعَلۡنَٰهَا نَكَٰلࣰا لِّمَا\nT;0;2:66:2:بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةࣰ لِّلۡمُتَّقِينَ¦2:67:1:وَإِذۡ قَالَ\nT;0;2:67:0:مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةࣰۖ قَالُوٓاْ\nT;0;2:67:2:أَتَتَّخِذُنَا هُزُوࣰاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ\nT;0;2:68:1:قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا\nT;0;2:68:0:بَقَرَةࣱ لَّا فَارِضࣱ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا\nT;0;2:68:2:تُؤۡمَرُونَ¦2:69:1:قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ\nT;0;2:69:2:يَقُولُ إِنَّهَا بَقَرَةࣱ صَفۡرَآءُ فَاقِعࣱ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ',
  '1;1;3;5\nT;0;2:70:1:قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ٱلۡبَقَرَ تَشَٰبَهَ عَلَيۡنَا وَإِنَّآ\nT;0;2:70:2:إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ¦2:71:1:قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةࣱ لَّا ذَلُولࣱ\nT;0;2:71:0:تُثِيرُ ٱلۡأَرۡضَ وَلَا تَسۡقِي ٱلۡحَرۡثَ مُسَلَّمَةࣱ لَّا شِيَةَ فِيهَاۚ قَالُواْ\nT;0;2:71:2:ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ¦2:72:1:وَإِذۡ\nT;0;2:72:2:قَتَلۡتُمۡ نَفۡسࣰا فَٱدَّٰرَٰءۡتُمۡ فِيهَاۖ وَٱللَّهُ مُخۡرِجࣱ مَّا كُنتُمۡ تَكۡتُمُونَ\nT;0;2:73:1:فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَٰلِكَ يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَيُرِيكُمۡ\nT;0;2:73:2:ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ¦2:74:1:ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ\nT;0;2:74:0:فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةࣰۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا يَتَفَجَّرُ\nT;0;2:74:0:مِنۡهُ ٱلۡأَنۡهَٰرُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ\nT;0;2:74:2:مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ\nT;0;2:75:1:۞ أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقࣱ مِّنۡهُمۡ\nT;0;2:75:0:يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ\nT;0;2:75:2:يَعۡلَمُونَ¦2:76:1:وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا\nT;0;2:76:0:خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضࣲ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ\nT;0;2:76:2:عَلَيۡكُمۡ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ',
  '1;2;0;\nT;0;2:77:3:أَوَلَا يَعۡلَمُونَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ\nT;0;2:78:1:وَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ\nT;0;2:78:2:إِلَّا يَظُنُّونَ¦2:79:1:فَوَيۡلࣱ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ\nT;0;2:79:0:ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنࣰا قَلِيلࣰاۖ\nT;0;2:79:2:فَوَيۡلࣱ لَّهُم مِّمَّا كَتَبَتۡ أَيۡدِيهِمۡ وَوَيۡلࣱ لَّهُم مِّمَّا يَكۡسِبُونَ\nT;0;2:80:1:وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامࣰا مَّعۡدُودَةࣰۚ قُلۡ\nT;0;2:80:0:أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدࣰا فَلَن يُخۡلِفَ ٱللَّهُ عَهۡدَهُۥٓۖ أَمۡ\nT;0;2:80:2:تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ¦2:81:1:بَلَىٰۚ مَن كَسَبَ سَيِّئَةࣰ\nT;0;2:81:0:وَأَحَٰطَتۡ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ\nT;0;2:81:2:فِيهَا خَٰلِدُونَ¦2:82:1:وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ\nT;0;2:82:2:أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ¦2:83:1:وَإِذۡ أَخَذۡنَا\nT;0;2:83:0:مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ\nT;0;2:83:0:إِحۡسَانࣰا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ\nT;0;2:83:0:لِلنَّاسِ حُسۡنࣰا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ\nT;0;2:83:2:تَوَلَّيۡتُمۡ إِلَّا قَلِيلࣰا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ',
  '1;2;0;\nT;0;2:84:1:وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ لَا تَسۡفِكُونَ دِمَآءَكُمۡ وَلَا تُخۡرِجُونَ\nT;0;2:84:2:أَنفُسَكُم مِّن دِيَٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ\nT;0;2:85:1:ثُمَّ أَنتُمۡ هَٰٓؤُلَآءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِيقࣰا\nT;0;2:85:0:مِّنكُم مِّن دِيَٰرِهِمۡ تَظَٰهَرُونَ عَلَيۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ\nT;0;2:85:0:وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ\nT;0;2:85:0:إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضࣲۚ\nT;0;2:85:0:فَمَا جَزَآءُ مَن يَفۡعَلُ ذَٰلِكَ مِنكُمۡ إِلَّا خِزۡيࣱ فِي ٱلۡحَيَوٰةِ\nT;0;2:85:0:ٱلدُّنۡيَاۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ\nT;0;2:85:2:بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ¦2:86:1:أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ\nT;0;2:86:2:ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ فَلَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنصَرُونَ\nT;0;2:87:1:وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ بَعۡدِهِۦ\nT;0;2:87:0:بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ\nT;0;2:87:0:ٱلۡقُدُسِۗ أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ\nT;0;2:87:2:ٱسۡتَكۡبَرۡتُمۡ فَفَرِيقࣰا كَذَّبۡتُمۡ وَفَرِيقࣰا تَقۡتُلُونَ¦2:88:1:وَقَالُواْ قُلُوبُنَا\nT;0;2:88:2:غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلࣰا مَّا يُؤۡمِنُونَ',
  '1;2;0;6\nT;0;2:89:1:وَلَمَّا جَآءَهُمۡ كِتَٰبࣱ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمۡ\nT;0;2:89:0:وَكَانُواْ مِن قَبۡلُ يَسۡتَفۡتِحُونَ عَلَى ٱلَّذِينَ كَفَرُواْ فَلَمَّا\nT;0;2:89:2:جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ\nT;0;2:90:1:بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ\nT;0;2:90:0:بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ\nT;0;2:90:2:فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبࣲۚ وَلِلۡكَٰفِرِينَ عَذَابࣱ مُّهِينࣱ\nT;0;2:91:1:وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ بِمَآ أَنزَلَ ٱللَّهُ قَالُواْ نُؤۡمِنُ بِمَآ أُنزِلَ\nT;0;2:91:0:عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقࣰا لِّمَا\nT;0;2:91:0:مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم\nT;0;2:91:2:مُّؤۡمِنِينَ¦2:92:1:۞ وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ ثُمَّ\nT;0;2:92:2:ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ¦2:93:1:وَإِذۡ\nT;0;2:93:0:أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ\nT;0;2:93:0:مَآ ءَاتَيۡنَٰكُم بِقُوَّةࣲ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا\nT;0;2:93:0:وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا\nT;0;2:93:2:يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ',
  '1;2;1;\nT;0;2:94:1:قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةࣰ مِّن\nT;0;2:94:2:دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ¦2:95:1:وَلَن\nT;0;2:95:2:يَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ\nT;0;2:96:1:وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةࣲ وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ\nT;0;2:96:0:يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةࣲ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ\nT;0;2:96:2:ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ¦2:97:1:قُلۡ مَن\nT;0;2:97:0:كَانَ عَدُوࣰّا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ\nT;0;2:97:2:ٱللَّهِ مُصَدِّقࣰا لِّمَا بَيۡنَ يَدَيۡهِ وَهُدࣰى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ\nT;0;2:98:1:مَن كَانَ عَدُوࣰّا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِيلَ\nT;0;2:98:2:وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوࣱّ لِّلۡكَٰفِرِينَ¦2:99:1:وَلَقَدۡ أَنزَلۡنَآ\nT;0;2:99:2:إِلَيۡكَ ءَايَٰتِۭ بَيِّنَٰتࣲۖ وَمَا يَكۡفُرُ بِهَآ إِلَّا ٱلۡفَٰسِقُونَ\nT;0;2:100:1:أَوَكُلَّمَا عَٰهَدُواْ عَهۡدࣰا نَّبَذَهُۥ فَرِيقࣱ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ\nT;0;2:100:2:لَا يُؤۡمِنُونَ¦2:101:1:وَلَمَّا جَآءَهُمۡ رَسُولࣱ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقࣱ\nT;0;2:101:0:لِّمَا مَعَهُمۡ نَبَذَ فَرِيقࣱ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ\nT;0;2:101:2:كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ',
  '1;2;1;\nT;0;2:102:1:وَٱتَّبَعُواْ مَا تَتۡلُواْ ٱلشَّيَٰطِينُ عَلَىٰ مُلۡكِ سُلَيۡمَٰنَۖ وَمَا كَفَرَ\nT;0;2:102:0:سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ\nT;0;2:102:0:ٱلسِّحۡرَ وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَۚ\nT;0;2:102:0:وَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةࣱ فَلَا\nT;0;2:102:0:تَكۡفُرۡۖ فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ\nT;0;2:102:0:وَزَوۡجِهِۦۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ\nT;0;2:102:0:وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُواْ لَمَنِ\nT;0;2:102:0:ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقࣲۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ\nT;0;2:102:2:أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ¦2:103:1:وَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ\nT;0;2:103:2:لَمَثُوبَةࣱ مِّنۡ عِندِ ٱللَّهِ خَيۡرࣱۚ لَّوۡ كَانُواْ يَعۡلَمُونَ\nT;0;2:104:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا\nT;0;2:104:2:وَٱسۡمَعُواْۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمࣱ¦2:105:1:مَّا يَوَدُّ\nT;0;2:105:0:ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ\nT;0;2:105:0:أَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرࣲ مِّن رَّبِّكُمۡۚ وَٱللَّهُ يَخۡتَصُّ\nT;0;2:105:2:بِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ',
  '1;2;2;7\nT;0;2:106:1:۞ مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرࣲ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ\nT;0;2:106:2:أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ¦2:107:1:أَلَمۡ تَعۡلَمۡ أَنَّ\nT;0;2:107:0:ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ\nT;0;2:107:2:ٱللَّهِ مِن وَلِيࣲّ وَلَا نَصِيرٍ¦2:108:1:أَمۡ تُرِيدُونَ أَن تَسۡـَٔلُواْ رَسُولَكُمۡ\nT;0;2:108:0:كَمَا سُئِلَ مُوسَىٰ مِن قَبۡلُۗ وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ\nT;0;2:108:2:فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ¦2:109:1:وَدَّ كَثِيرࣱ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ\nT;0;2:109:0:لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدࣰا\nT;0;2:109:0:مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُواْ\nT;0;2:109:0:وَٱصۡفَحُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦٓۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ\nT;0;2:109:2:قَدِيرࣱ¦2:110:1:وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُواْ\nT;0;2:110:0:لِأَنفُسِكُم مِّنۡ خَيۡرࣲ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ\nT;0;2:110:2:بَصِيرࣱ¦2:111:1:وَقَالُواْ لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا\nT;0;2:111:0:أَوۡ نَصَٰرَىٰۗ تِلۡكَ أَمَانِيُّهُمۡۗ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ\nT;0;2:111:2:صَٰدِقِينَ¦2:112:1:بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنࣱ فَلَهُۥٓ\nT;0;2:112:2:أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ',
  '1;2;2;\nT;0;2:113:1:وَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءࣲ وَقَالَتِ ٱلنَّصَٰرَىٰ\nT;0;2:113:0:لَيۡسَتِ ٱلۡيَهُودُ عَلَىٰ شَيۡءࣲ وَهُمۡ يَتۡلُونَ ٱلۡكِتَٰبَۗ كَذَٰلِكَ\nT;0;2:113:0:قَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَهُمۡ\nT;0;2:113:2:يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ¦2:114:1:وَمَنۡ أَظۡلَمُ مِمَّن\nT;0;2:114:0:مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ\nT;0;2:114:0:أُوْلَٰٓئِكَ مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ لَهُمۡ فِي\nT;0;2:114:2:ٱلدُّنۡيَا خِزۡيࣱ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمࣱ¦2:115:1:وَلِلَّهِ ٱلۡمَشۡرِقُ\nT;0;2:115:2:وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمࣱ\nT;0;2:116:1:وَقَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدࣰاۗ سُبۡحَٰنَهُۥۖ بَل لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ\nT;0;2:116:2:وَٱلۡأَرۡضِۖ كُلࣱّ لَّهُۥ قَٰنِتُونَ¦2:117:1:بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ\nT;0;2:117:2:وَإِذَا قَضَىٰٓ أَمۡرࣰا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ¦2:118:1:وَقَالَ\nT;0;2:118:0:ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةࣱۗ\nT;0;2:118:0:كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَٰبَهَتۡ\nT;0;2:118:2:قُلُوبُهُمۡۗ قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ لِقَوۡمࣲ يُوقِنُونَ¦2:119:1:إِنَّآ أَرۡسَلۡنَٰكَ\nT;0;2:119:2:بِٱلۡحَقِّ بَشِيرࣰا وَنَذِيرࣰاۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ',
  '1;2;2;8\nT;0;2:120:1:وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ\nT;0;2:120:0:إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ ٱلَّذِي\nT;0;2:120:2:جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيࣲّ وَلَا نَصِيرٍ¦2:121:1:ٱلَّذِينَ\nT;0;2:121:0:ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ وَمَن\nT;0;2:121:2:يَكۡفُرۡ بِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ¦2:122:1:يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ\nT;0;2:122:2:ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ¦2:123:1:وَٱتَّقُواْ يَوۡمࣰا\nT;0;2:123:0:لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسࣲ شَيۡـࣰٔا وَلَا يُقۡبَلُ مِنۡهَا عَدۡلࣱ وَلَا تَنفَعُهَا\nT;0;2:123:2:شَفَٰعَةࣱ وَلَا هُمۡ يُنصَرُونَ¦2:124:1:۞ وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتࣲ\nT;0;2:124:0:فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامࣰاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ\nT;0;2:124:2:لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ¦2:125:1:وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةࣰ لِّلنَّاسِ\nT;0;2:125:0:وَأَمۡنࣰا وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلࣰّىۖ وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ\nT;0;2:125:2:وَإِسۡمَٰعِيلَ أَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ\nT;0;2:126:1:وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنࣰا وَٱرۡزُقۡ أَهۡلَهُۥ\nT;0;2:126:0:مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ\nT;0;2:126:2:فَأُمَتِّعُهُۥ قَلِيلࣰا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ',
  '1;2;3;\nT;0;2:127:1:وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ\nT;0;2:127:2:مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ¦2:128:1:رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ\nT;0;2:128:0:لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةࣰ مُّسۡلِمَةࣰ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ\nT;0;2:128:2:إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ¦2:129:1:رَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولࣰا مِّنۡهُمۡ\nT;0;2:129:0:يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ\nT;0;2:129:2:وَيُزَكِّيهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦2:130:1:وَمَن يَرۡغَبُ عَن مِّلَّةِ\nT;0;2:130:0:إِبۡرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ\nT;0;2:130:2:وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ¦2:131:1:إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ\nT;0;2:131:2:قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ¦2:132:1:وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ\nT;0;2:132:0:وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ\nT;0;2:132:2:إِلَّا وَأَنتُم مُّسۡلِمُونَ¦2:133:1:أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ\nT;0;2:133:0:ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ\nT;0;2:133:0:إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهࣰا\nT;0;2:133:2:وَٰحِدࣰا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ¦2:134:1:تِلۡكَ أُمَّةࣱ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ\nT;0;2:134:2:وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ',
  '1;2;3;\nT;0;2:135:1:وَقَالُواْ كُونُواْ هُودًا أَوۡ نَصَٰرَىٰ تَهۡتَدُواْۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ\nT;0;2:135:2:حَنِيفࣰاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ¦2:136:1:قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ\nT;0;2:136:0:أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ\nT;0;2:136:0:وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن\nT;0;2:136:2:رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدࣲ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ\nT;0;2:137:1:فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ\nT;0;2:137:2:فَإِنَّمَا هُمۡ فِي شِقَاقࣲۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\nT;0;2:138:1:صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةࣰۖ وَنَحۡنُ لَهُۥ\nT;0;2:138:2:عَٰبِدُونَ¦2:139:1:قُلۡ أَتُحَآجُّونَنَا فِي ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ\nT;0;2:139:2:وَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ\nT;0;2:140:1:أَمۡ تَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ\nT;0;2:140:0:وَٱلۡأَسۡبَاطَ كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ\nT;0;2:140:0:ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ\nT;0;2:140:2:بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ¦2:141:1:تِلۡكَ أُمَّةࣱ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ\nT;0;2:141:2:وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ',
  '2;3;0;9\nT;0;2:142:1:۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ\nT;0;2:142:0:عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطࣲ\nT;0;2:142:2:مُّسۡتَقِيمࣲ¦2:143:1:وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةࣰ وَسَطࣰا لِّتَكُونُواْ\nT;0;2:143:0:شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدࣰاۗ وَمَا\nT;0;2:143:0:جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ\nT;0;2:143:0:مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ\nT;0;2:143:0:هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ\nT;0;2:143:2:بِٱلنَّاسِ لَرَءُوفࣱ رَّحِيمࣱ¦2:144:1:قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ\nT;0;2:144:0:فَلَنُوَلِّيَنَّكَ قِبۡلَةࣰ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ\nT;0;2:144:0:ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ\nT;0;2:144:0:ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ\nT;0;2:144:2:بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ¦2:145:1:وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ\nT;0;2:145:0:بِكُلِّ ءَايَةࣲ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعࣲ قِبۡلَتَهُمۡۚ\nT;0;2:145:0:وَمَا بَعۡضُهُم بِتَابِعࣲ قِبۡلَةَ بَعۡضࣲۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ\nT;0;2:145:2:بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذࣰا لَّمِنَ ٱلظَّٰلِمِينَ',
  '2;3;0;\nT;0;2:146:1:ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ\nT;0;2:146:2:وَإِنَّ فَرِيقࣰا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ¦2:147:1:ٱلۡحَقُّ\nT;0;2:147:2:مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ¦2:148:1:وَلِكُلࣲّ وِجۡهَةٌ\nT;0;2:148:0:هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ\nT;0;2:148:2:جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ¦2:149:1:وَمِنۡ حَيۡثُ خَرَجۡتَ\nT;0;2:149:0:فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ\nT;0;2:149:2:وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ¦2:150:1:وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ\nT;0;2:150:0:وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ\nT;0;2:150:0:وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ\nT;0;2:150:0:ظَلَمُواْ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ\nT;0;2:150:2:وَلَعَلَّكُمۡ تَهۡتَدُونَ¦2:151:1:كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولࣰا مِّنكُمۡ يَتۡلُواْ\nT;0;2:151:0:عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ\nT;0;2:151:2:وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ¦2:152:1:فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ\nT;0;2:152:2:وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ¦2:153:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nT;0;2:153:2:ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ',
  '2;3;0;10\nT;0;2:154:1:وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢۚ بَلۡ أَحۡيَآءࣱ وَلَٰكِن\nT;0;2:154:2:لَّا تَشۡعُرُونَ¦2:155:1:وَلَنَبۡلُوَنَّكُم بِشَيۡءࣲ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ\nT;0;2:155:2:وَنَقۡصࣲ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّٰبِرِينَ\nT;0;2:156:3:ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةࣱ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ\nT;0;2:157:1:أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتࣱ مِّن رَّبِّهِمۡ وَرَحۡمَةࣱۖ وَأُوْلَٰٓئِكَ\nT;0;2:157:2:هُمُ ٱلۡمُهۡتَدُونَ¦2:158:1:۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ\nT;0;2:158:0:فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ\nT;0;2:158:2:وَمَن تَطَوَّعَ خَيۡرࣰا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ¦2:159:1:إِنَّ ٱلَّذِينَ\nT;0;2:159:0:يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَيَّنَّٰهُ\nT;0;2:159:2:لِلنَّاسِ فِي ٱلۡكِتَٰبِ أُوْلَٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ وَيَلۡعَنُهُمُ ٱللَّٰعِنُونَ\nT;0;2:160:1:إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ\nT;0;2:160:2:وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ¦2:161:1:إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ\nT;0;2:161:2:كُفَّارٌ أُوْلَٰٓئِكَ عَلَيۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ\nT;0;2:162:3:خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ\nT;0;2:163:3:وَإِلَٰهُكُمۡ إِلَٰهࣱ وَٰحِدࣱۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ',
  '2;3;1;\nT;0;2:164:1:إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ\nT;0;2:164:0:وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ\nT;0;2:164:0:مِنَ ٱلسَّمَآءِ مِن مَّآءࣲ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا\nT;0;2:164:0:مِن كُلِّ دَآبَّةࣲ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ\nT;0;2:164:2:ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَعۡقِلُونَ¦2:165:1:وَمِنَ ٱلنَّاسِ\nT;0;2:165:0:مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادࣰا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ\nT;0;2:165:0:ءَامَنُوٓاْ أَشَدُّ حُبࣰّا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ\nT;0;2:165:2:ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعࣰا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ\nT;0;2:166:1:إِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ\nT;0;2:166:2:وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ¦2:167:1:وَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ\nT;0;2:167:0:لَنَا كَرَّةࣰ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ\nT;0;2:167:2:أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ\nT;0;2:168:1:يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلࣰا طَيِّبࣰا وَلَا تَتَّبِعُواْ\nT;0;2:168:2:خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِينٌ¦2:169:1:إِنَّمَا يَأۡمُرُكُم\nT;0;2:169:2:بِٱلسُّوٓءِ وَٱلۡفَحۡشَآءِ وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ',
  '2;3;1;\nT;0;2:170:1:وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا\nT;0;2:170:0:عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـࣰٔا وَلَا\nT;0;2:170:2:يَهۡتَدُونَ¦2:171:1:وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ\nT;0;2:171:2:بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءࣰ وَنِدَآءࣰۚ صُمُّۢ بُكۡمٌ عُمۡيࣱ فَهُمۡ لَا يَعۡقِلُونَ\nT;0;2:172:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ\nT;0;2:172:2:وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ¦2:173:1:إِنَّمَا حَرَّمَ\nT;0;2:173:0:عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ\nT;0;2:173:0:ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغࣲ وَلَا عَادࣲ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ\nT;0;2:173:2:غَفُورࣱ رَّحِيمٌ¦2:174:1:إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ\nT;0;2:174:0:ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنࣰا قَلِيلًا أُوْلَٰٓئِكَ مَا يَأۡكُلُونَ\nT;0;2:174:0:فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ\nT;0;2:174:2:وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ¦2:175:1:أُوْلَٰٓئِكَ ٱلَّذِينَ\nT;0;2:175:0:ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَآ\nT;0;2:175:2:أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ¦2:176:1:ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّۗ\nT;0;2:176:2:وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدࣲ',
  '2;3;2;11\nT;0;2:177:1:۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ\nT;0;2:177:0:وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ\nT;0;2:177:0:وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ\nT;0;2:177:0:وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ\nT;0;2:177:0:ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ\nT;0;2:177:0:وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ\nT;0;2:177:2:صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ¦2:178:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ\nT;0;2:178:0:عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ\nT;0;2:178:0:بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءࣱ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ\nT;0;2:178:0:إِلَيۡهِ بِإِحۡسَٰنࣲۗ ذَٰلِكَ تَخۡفِيفࣱ مِّن رَّبِّكُمۡ وَرَحۡمَةࣱۗ فَمَنِ ٱعۡتَدَىٰ\nT;0;2:178:2:بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمࣱ¦2:179:1:وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةࣱ يَٰٓأُوْلِي\nT;0;2:179:2:ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ¦2:180:1:كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ\nT;0;2:180:0:أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ\nT;0;2:180:2:بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ¦2:181:1:فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ\nT;0;2:181:2:فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمࣱ',
  '2;3;2;\nT;0;2:182:1:فَمَنۡ خَافَ مِن مُّوصࣲ جَنَفًا أَوۡ إِثۡمࣰا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ\nT;0;2:182:2:عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ¦2:183:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ\nT;0;2:183:0:عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ\nT;0;2:183:2:لَعَلَّكُمۡ تَتَّقُونَ¦2:184:1:أَيَّامࣰا مَّعۡدُودَٰتࣲۚ فَمَن كَانَ\nT;0;2:184:0:مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى\nT;0;2:184:0:ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةࣱ طَعَامُ مِسۡكِينࣲۖ فَمَن تَطَوَّعَ خَيۡرࣰا\nT;0;2:184:2:فَهُوَ خَيۡرࣱ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\nT;0;2:185:1:شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدࣰى لِّلنَّاسِ\nT;0;2:185:0:وَبَيِّنَٰتࣲ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ\nT;0;2:185:0:ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ\nT;0;2:185:0:مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ\nT;0;2:185:0:ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا\nT;0;2:185:2:هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ¦2:186:1:وَإِذَا سَأَلَكَ\nT;0;2:186:0:عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ\nT;0;2:186:2:فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ',
  '2;3;2;12\nT;0;2:187:1:أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ\nT;0;2:187:0:لِبَاسࣱ لَّكُمۡ وَأَنتُمۡ لِبَاسࣱ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ\nT;0;2:187:0:تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ\nT;0;2:187:0:بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ\nT;0;2:187:0:حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ\nT;0;2:187:0:ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ\nT;0;2:187:0:عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ\nT;0;2:187:2:يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ¦2:188:1:وَلَا تَأۡكُلُوٓاْ\nT;0;2:188:0:أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ\nT;0;2:188:2:لِتَأۡكُلُواْ فَرِيقࣰا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ\nT;0;2:189:1:۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ\nT;0;2:189:0:وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ\nT;0;2:189:0:مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ\nT;0;2:189:2:لَعَلَّكُمۡ تُفۡلِحُونَ¦2:190:1:وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ\nT;0;2:190:2:يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ',
  '2;3;3;\nT;0;2:191:1:وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ\nT;0;2:191:0:أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ\nT;0;2:191:2:فِيهِۖ فَإِن قَٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ¦2:192:1:فَإِنِ ٱنتَهَوۡاْ\nT;0;2:192:2:فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ¦2:193:1:وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةࣱ وَيَكُونَ\nT;0;2:193:2:ٱلدِّينُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ¦2:194:1:ٱلشَّهۡرُ ٱلۡحَرَامُ\nT;0;2:194:0:بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَٰتُ قِصَاصࣱۚ فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ\nT;0;2:194:0:عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ\nT;0;2:194:2:ٱلۡمُتَّقِينَ¦2:195:1:وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ\nT;0;2:195:2:وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ¦2:196:1:وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ\nT;0;2:196:0:فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ\nT;0;2:196:0:ٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذࣰى مِّن رَّأۡسِهِۦ فَفِدۡيَةࣱ\nT;0;2:196:0:مِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكࣲۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ\nT;0;2:196:0:فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامࣲ فِي ٱلۡحَجِّ\nT;0;2:196:0:وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةࣱ كَامِلَةࣱۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي\nT;0;2:196:2:ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ',
  '2;3;3;\nT;0;2:197:1:ٱلۡحَجُّ أَشۡهُرࣱ مَّعۡلُومَٰتࣱۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا\nT;0;2:197:0:رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ\nT;0;2:197:0:خَيۡرࣲ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ\nT;0;2:197:2:وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ¦2:198:1:لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ\nT;0;2:198:0:أَن تَبۡتَغُواْ فَضۡلࣰا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ\nT;0;2:198:0:عَرَفَٰتࣲ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ\nT;0;2:198:0:وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ\nT;0;2:198:2:لَمِنَ ٱلضَّآلِّينَ¦2:199:1:ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ\nT;0;2:199:2:ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ\nT;0;2:200:1:فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ\nT;0;2:200:0:ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرࣰاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ\nT;0;2:200:2:رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقࣲ\nT;0;2:201:1:وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةࣰ\nT;0;2:201:2:وَفِي ٱلۡأٓخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ¦2:202:1:أُوْلَٰٓئِكَ\nT;0;2:202:2:لَهُمۡ نَصِيبࣱ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ',
  '2;4;0;13\nT;0;2:203:1:۞ وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامࣲ مَّعۡدُودَٰتࣲۚ فَمَن تَعَجَّلَ فِي\nT;0;2:203:0:يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ\nT;0;2:203:2:ٱتَّقَىٰۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ\nT;0;2:204:1:وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nT;0;2:204:2:وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ\nT;0;2:205:1:وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ\nT;0;2:205:2:وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ¦2:206:1:وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ\nT;0;2:206:0:أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ\nT;0;2:206:2:ٱلۡمِهَادُ¦2:207:1:وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ\nT;0;2:207:2:مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ¦2:208:1:يَٰٓأَيُّهَا ٱلَّذِينَ\nT;0;2:208:0:ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةࣰ وَلَا تَتَّبِعُواْ خُطُوَٰتِ\nT;0;2:208:2:ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِينࣱ¦2:209:1:فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ\nT;0;2:209:2:مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ\nT;0;2:210:1:هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلࣲ مِّنَ ٱلۡغَمَامِ\nT;0;2:210:2:وَٱلۡمَلَٰٓئِكَةُ وَقُضِيَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ',
  '2;4;0;\nT;0;2:211:1:سَلۡ بَنِيٓ إِسۡرَٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةࣲۗ وَمَن يُبَدِّلۡ نِعۡمَةَ\nT;0;2:211:2:ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ¦2:212:1:زُيِّنَ\nT;0;2:212:0:لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ\nT;0;2:212:2:ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابࣲ\nT;0;2:213:1:كَانَ ٱلنَّاسُ أُمَّةࣰ وَٰحِدَةࣰ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ\nT;0;2:213:0:وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ\nT;0;2:213:0:فِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ\nT;0;2:213:0:مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ\nT;0;2:213:0:لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ\nT;0;2:213:2:إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمٍ¦2:214:1:أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا\nT;0;2:214:0:يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ\nT;0;2:214:0:وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ\nT;0;2:214:2:ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبࣱ¦2:215:1:يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ\nT;0;2:215:0:مَآ أَنفَقۡتُم مِّنۡ خَيۡرࣲ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ\nT;0;2:215:2:وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمࣱ',
  '2;4;0;14\nT;0;2:216:1:كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهࣱ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ\nT;0;2:216:0:شَيۡـࣰٔا وَهُوَ خَيۡرࣱ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـࣰٔا وَهُوَ شَرࣱّ\nT;0;2:216:2:لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ¦2:217:1:يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ\nT;0;2:217:0:ٱلۡحَرَامِ قِتَالࣲ فِيهِۖ قُلۡ قِتَالࣱ فِيهِ كَبِيرࣱۚ وَصَدٌّ عَن سَبِيلِ\nT;0;2:217:0:ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ\nT;0;2:217:0:أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا يَزَالُونَ\nT;0;2:217:0:يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ وَمَن\nT;0;2:217:0:يَرۡتَدِدۡ مِنكُمۡ عَن دِينِهِۦ فَيَمُتۡ وَهُوَ كَافِرࣱ فَأُوْلَٰٓئِكَ\nT;0;2:217:0:حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ\nT;0;2:217:2:ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ¦2:218:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ\nT;0;2:218:0:هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَٰٓئِكَ يَرۡجُونَ رَحۡمَتَ\nT;0;2:218:2:ٱللَّهِۚ وَٱللَّهُ غَفُورࣱ رَّحِيمࣱ¦2:219:1:۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ\nT;0;2:219:0:قُلۡ فِيهِمَآ إِثۡمࣱ كَبِيرࣱ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ\nT;0;2:219:0:مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ\nT;0;2:219:2:يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ',
  '2;4;1;\nT;0;2:220:1:فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحࣱ لَّهُمۡ\nT;0;2:220:0:خَيۡرࣱۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ\nT;0;2:220:2:ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمࣱ\nT;0;2:221:1:وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةࣱ مُّؤۡمِنَةٌ\nT;0;2:221:0:خَيۡرࣱ مِّن مُّشۡرِكَةࣲ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ\nT;0;2:221:0:حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدࣱ مُّؤۡمِنٌ خَيۡرࣱ مِّن مُّشۡرِكࣲ وَلَوۡ أَعۡجَبَكُمۡۗ\nT;0;2:221:0:أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ\nT;0;2:221:2:بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ\nT;0;2:222:1:وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذࣰى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي\nT;0;2:222:0:ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ\nT;0;2:222:2:مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ\nT;0;2:223:1:نِسَآؤُكُمۡ حَرۡثࣱ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ\nT;0;2:223:0:لِأَنفُسِكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ\nT;0;2:223:2:ٱلۡمُؤۡمِنِينَ¦2:224:1:وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةࣰ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ\nT;0;2:224:2:وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمࣱ',
  '2;4;1;\nT;0;2:225:1:لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ\nT;0;2:225:2:قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمࣱ¦2:226:1:لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ\nT;0;2:226:2:أَرۡبَعَةِ أَشۡهُرࣲۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ¦2:227:1:وَإِنۡ عَزَمُواْ\nT;0;2:227:2:ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمࣱ¦2:228:1:وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ\nT;0;2:228:0:ثَلَٰثَةَ قُرُوٓءࣲۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ\nT;0;2:228:0:إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي\nT;0;2:228:0:ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحࣰاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ\nT;0;2:228:2:وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةࣱۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ¦2:229:1:ٱلطَّلَٰقُ مَرَّتَانِۖ\nT;0;2:229:0:فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنࣲۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ\nT;0;2:229:0:مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ\nT;0;2:229:0:فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ\nT;0;2:229:0:بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَٰٓئِكَ\nT;0;2:229:2:هُمُ ٱلظَّٰلِمُونَ¦2:230:1:فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا\nT;0;2:230:0:غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن\nT;0;2:230:2:يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمࣲ يَعۡلَمُونَ',
  '2;4;1;15\nT;0;2:231:1:وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ\nT;0;2:231:0:أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفࣲۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارࣰا لِّتَعۡتَدُواْۚ وَمَن\nT;0;2:231:0:يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوࣰاۚ\nT;0;2:231:0:وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ\nT;0;2:231:2:يَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمࣱ¦2:232:1:وَإِذَا\nT;0;2:232:0:طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ\nT;0;2:232:0:أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ\nT;0;2:232:0:مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ\nT;0;2:232:2:يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ¦2:233:1:۞ وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ\nT;0;2:233:0:كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ\nT;0;2:233:0:وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ\nT;0;2:233:0:وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودࣱ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ\nT;0;2:233:0:أَرَادَا فِصَالًا عَن تَرَاضࣲ مِّنۡهُمَا وَتَشَاوُرࣲ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ\nT;0;2:233:0:أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ\nT;0;2:233:2:ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرࣱ',
  '2;4;2;\nT;0;2:234:1:وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجࣰا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ\nT;0;2:234:0:أَرۡبَعَةَ أَشۡهُرࣲ وَعَشۡرࣰاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ\nT;0;2:234:2:فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ\nT;0;2:235:1:وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ\nT;0;2:235:0:أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ\nT;0;2:235:0:وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلࣰا مَّعۡرُوفࣰاۚ\nT;0;2:235:0:وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ\nT;0;2:235:0:وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ\nT;0;2:235:2:أَنَّ ٱللَّهَ غَفُورٌ حَلِيمࣱ¦2:236:1:لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ\nT;0;2:236:0:مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةࣰۚ وَمَتِّعُوهُنَّ عَلَى\nT;0;2:236:0:ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى\nT;0;2:236:2:ٱلۡمُحۡسِنِينَ¦2:237:1:وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ\nT;0;2:237:0:فَرَضۡتُمۡ لَهُنَّ فَرِيضَةࣰ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ\nT;0;2:237:0:أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ\nT;0;2:237:2:وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ',
  '2;4;2;16\nT;0;2:238:1:حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ\nT;0;2:238:2:قَٰنِتِينَ¦2:239:1:فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانࣰاۖ فَإِذَآ أَمِنتُمۡ\nT;0;2:239:2:فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ\nT;0;2:240:1:وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجࣰا\nT;0;2:240:0:وَصِيَّةࣰ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجࣲۚ فَإِنۡ\nT;0;2:240:0:خَرَجۡنَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ\nT;0;2:240:2:مِن مَّعۡرُوفࣲۗ وَٱللَّهُ عَزِيزٌ حَكِيمࣱ¦2:241:1:وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ\nT;0;2:241:2:بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ¦2:242:1:كَذَٰلِكَ يُبَيِّنُ\nT;0;2:242:2:ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ¦2:243:1:۞ أَلَمۡ تَرَ\nT;0;2:243:0:إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ\nT;0;2:243:0:فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ\nT;0;2:243:2:عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ\nT;0;2:244:3:وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمࣱ¦2:245:1:مَّن\nT;0;2:245:0:ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنࣰا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافࣰا\nT;0;2:245:2:كَثِيرَةࣰۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ',
  '2;4;3;\nT;0;2:246:1:أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ\nT;0;2:246:0:قَالُواْ لِنَبِيࣲّ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكࣰا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ\nT;0;2:246:0:قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ\nT;0;2:246:0:قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا\nT;0;2:246:0:مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ\nT;0;2:246:2:إِلَّا قَلِيلࣰا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ¦2:247:1:وَقَالَ لَهُمۡ\nT;0;2:247:0:نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكࣰاۚ\nT;0;2:247:0:قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ\nT;0;2:247:0:بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةࣰ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ\nT;0;2:247:0:ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةࣰ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ\nT;0;2:247:2:وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمࣱ\nT;0;2:248:1:وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ\nT;0;2:248:0:ٱلتَّابُوتُ فِيهِ سَكِينَةࣱ مِّن رَّبِّكُمۡ وَبَقِيَّةࣱ مِّمَّا\nT;0;2:248:0:تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَٰٓئِكَةُۚ\nT;0;2:248:2:إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ',
  '2;4;3;\nT;0;2:249:1:فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم\nT;0;2:249:0:بِنَهَرࣲ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ\nT;0;2:249:0:فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ\nT;0;2:249:0:إِلَّا قَلِيلࣰا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ\nT;0;2:249:0:مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ\nT;0;2:249:0:قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةࣲ\nT;0;2:249:0:قَلِيلَةٍ غَلَبَتۡ فِئَةࣰ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ\nT;0;2:249:2:ٱلصَّٰبِرِينَ¦2:250:1:وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ\nT;0;2:250:0:رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرࣰا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا\nT;0;2:250:2:عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ¦2:251:1:فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ\nT;0;2:251:0:وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ\nT;0;2:251:0:وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ\nT;0;2:251:0:بَعۡضَهُم بِبَعۡضࣲ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو\nT;0;2:251:2:فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ¦2:252:1:تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا\nT;0;2:252:2:عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ',
  '3;5;0;17\nT;0;2:253:1:۞ تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ\nT;0;2:253:0:وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتࣲۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ\nT;0;2:253:0:وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ\nT;0;2:253:0:بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ\nT;0;2:253:0:فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ\nT;0;2:253:2:وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ¦2:254:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ\nT;0;2:254:0:مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمࣱ لَّا بَيۡعࣱ فِيهِ وَلَا خُلَّةࣱ وَلَا\nT;0;2:254:2:شَفَٰعَةࣱۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ¦2:255:1:ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ\nT;0;2:255:0:ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةࣱ وَلَا نَوۡمࣱۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ\nT;0;2:255:0:وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ\nT;0;2:255:0:مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءࣲ مِّنۡ عِلۡمِهِۦٓ إِلَّا\nT;0;2:255:0:بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ\nT;0;2:255:2:وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ¦2:256:1:لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ\nT;0;2:256:0:ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ\nT;0;2:256:2:بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ',
  '3;5;0;\nT;0;2:257:1:ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ\nT;0;2:257:0:وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ\nT;0;2:257:0:ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا\nT;0;2:257:2:خَٰلِدُونَ¦2:258:1:أَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِـۧمَ فِي رَبِّهِۦٓ\nT;0;2:258:0:أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّيَ ٱلَّذِي يُحۡيِۦ\nT;0;2:258:0:وَيُمِيتُ قَالَ أَنَا۠ أُحۡيِۦ وَأُمِيتُۖ قَالَ إِبۡرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأۡتِي\nT;0;2:258:0:بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِي\nT;0;2:258:2:كَفَرَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ¦2:259:1:أَوۡ كَٱلَّذِي\nT;0;2:259:0:مَرَّ عَلَىٰ قَرۡيَةࣲ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ\nT;0;2:259:0:هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامࣲ ثُمَّ بَعَثَهُۥۖ\nT;0;2:259:0:قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمࣲۖ قَالَ بَل\nT;0;2:259:0:لَّبِثۡتَ مِاْئَةَ عَامࣲ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ\nT;0;2:259:0:وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةࣰ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى\nT;0;2:259:0:ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمࣰاۚ فَلَمَّا\nT;0;2:259:2:تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ',
  '3;5;0;18\nT;0;2:260:1:وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ\nT;0;2:260:0:تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةࣰ مِّنَ\nT;0;2:260:0:ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلࣲ مِّنۡهُنَّ جُزۡءࣰا\nT;0;2:260:2:ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيࣰاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمࣱ\nT;0;2:261:1:مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ\nT;0;2:261:0:أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةࣲ مِّاْئَةُ حَبَّةࣲۗ وَٱللَّهُ\nT;0;2:261:2:يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ¦2:262:1:ٱلَّذِينَ يُنفِقُونَ\nT;0;2:262:0:أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنࣰّا وَلَآ\nT;0;2:262:0:أَذࣰى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ\nT;0;2:262:2:يَحۡزَنُونَ¦2:263:1:۞ قَوۡلࣱ مَّعۡرُوفࣱ وَمَغۡفِرَةٌ خَيۡرࣱ مِّن صَدَقَةࣲ\nT;0;2:263:2:يَتۡبَعُهَآ أَذࣰىۗ وَٱللَّهُ غَنِيٌّ حَلِيمࣱ¦2:264:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nT;0;2:264:0:لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ\nT;0;2:264:0:رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ\nT;0;2:264:0:صَفۡوَانٍ عَلَيۡهِ تُرَابࣱ فَأَصَابَهُۥ وَابِلࣱ فَتَرَكَهُۥ صَلۡدࣰاۖ لَّا يَقۡدِرُونَ\nT;0;2:264:2:عَلَىٰ شَيۡءࣲ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ',
  '3;5;1;\nT;0;2:265:1:وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ\nT;0;2:265:0:وَتَثۡبِيتࣰا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلࣱ\nT;0;2:265:0:فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلࣱ فَطَلࣱّۗ\nT;0;2:265:2:وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ¦2:266:1:أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ\nT;0;2:266:0:جَنَّةࣱ مِّن نَّخِيلࣲ وَأَعۡنَابࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ\nT;0;2:266:0:فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةࣱ\nT;0;2:266:0:ضُعَفَآءُ فَأَصَابَهَآ إِعۡصَارࣱ فِيهِ نَارࣱ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ\nT;0;2:266:2:يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ¦2:267:1:يَٰٓأَيُّهَا\nT;0;2:267:0:ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا\nT;0;2:267:0:لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ\nT;0;2:267:0:وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ\nT;0;2:267:2:حَمِيدٌ¦2:268:1:ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ\nT;0;2:268:2:وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةࣰ مِّنۡهُ وَفَضۡلࣰاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمࣱ\nT;0;2:269:1:يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ\nT;0;2:269:2:أُوتِيَ خَيۡرࣰا كَثِيرࣰاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ',
  '3;5;1;19\nT;0;2:270:1:وَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرࣲ فَإِنَّ ٱللَّهَ\nT;0;2:270:2:يَعۡلَمُهُۥۗ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٍ¦2:271:1:إِن تُبۡدُواْ\nT;0;2:271:0:ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا\nT;0;2:271:0:ٱلۡفُقَرَآءَ فَهُوَ خَيۡرࣱ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن\nT;0;2:271:2:سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ¦2:272:1:۞ لَّيۡسَ\nT;0;2:272:0:عَلَيۡكَ هُدَىٰهُمۡ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا\nT;0;2:272:0:تُنفِقُواْ مِنۡ خَيۡرࣲ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا\nT;0;2:272:0:ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُواْ مِنۡ خَيۡرࣲ يُوَفَّ إِلَيۡكُمۡ\nT;0;2:272:2:وَأَنتُمۡ لَا تُظۡلَمُونَ¦2:273:1:لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ\nT;0;2:273:0:فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبࣰا فِي ٱلۡأَرۡضِ\nT;0;2:273:0:يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم\nT;0;2:273:0:بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافࣰاۗ وَمَا تُنفِقُواْ مِنۡ\nT;0;2:273:2:خَيۡرࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ¦2:274:1:ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم\nT;0;2:274:0:بِٱلَّيۡلِ وَٱلنَّهَارِ سِرࣰّا وَعَلَانِيَةࣰ فَلَهُمۡ أَجۡرُهُمۡ عِندَ\nT;0;2:274:2:رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ',
  '3;5;2;\nT;0;2:275:1:ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي\nT;0;2:275:0:يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ\nT;0;2:275:0:مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ\nT;0;2:275:0:مَوۡعِظَةࣱ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ\nT;0;2:275:2:عَادَ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ¦2:276:1:يَمۡحَقُ\nT;0;2:276:2:ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ\nT;0;2:277:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ\nT;0;2:277:0:وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ\nT;0;2:277:2:وَلَا هُمۡ يَحۡزَنُونَ¦2:278:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ\nT;0;2:278:2:وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ¦2:279:1:فَإِن لَّمۡ تَفۡعَلُواْ\nT;0;2:279:0:فَأۡذَنُواْ بِحَرۡبࣲ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ\nT;0;2:279:2:أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ¦2:280:1:وَإِن كَانَ\nT;0;2:280:0:ذُو عُسۡرَةࣲ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةࣲۚ وَأَن تَصَدَّقُواْ خَيۡرࣱ لَّكُمۡ\nT;0;2:280:2:إِن كُنتُمۡ تَعۡلَمُونَ¦2:281:1:وَٱتَّقُواْ يَوۡمࣰا تُرۡجَعُونَ فِيهِ إِلَى\nT;0;2:281:2:ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ',
  '3;5;2;\nT;0;2:282:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّى\nT;0;2:282:0:فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ\nT;0;2:282:0:كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ\nT;0;2:282:0:ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـࣰٔاۚ\nT;0;2:282:0:فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ\nT;0;2:282:0:أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ\nT;0;2:282:0:مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلࣱ وَٱمۡرَأَتَانِ\nT;0;2:282:0:مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ\nT;0;2:282:0:إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ\nT;0;2:282:0:أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ\nT;0;2:282:0:عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ\nT;0;2:282:0:تِجَٰرَةً حَاضِرَةࣰ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ\nT;0;2:282:0:أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبࣱ\nT;0;2:282:0:وَلَا شَهِيدࣱۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ\nT;0;2:282:2:ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣱ',
  '3;5;3;20\nT;0;2:283:1:۞ وَإِن كُنتُمۡ عَلَىٰ سَفَرࣲ وَلَمۡ تَجِدُواْ كَاتِبࣰا فَرِهَٰنࣱ مَّقۡبُوضَةࣱۖ\nT;0;2:283:0:فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضࣰا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ\nT;0;2:283:0:ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ\nT;0;2:283:2:ءَاثِمࣱ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمࣱ¦2:284:1:لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ\nT;0;2:284:0:وَمَا فِي ٱلۡأَرۡضِۗ وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ\nT;0;2:284:0:يُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۗ\nT;0;2:284:2:وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ¦2:285:1:ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ\nT;0;2:285:0:مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ\nT;0;2:285:0:وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدࣲ مِّن رُّسُلِهِۦۚ وَقَالُواْ\nT;0;2:285:2:سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ¦2:286:1:لَا يُكَلِّفُ\nT;0;2:286:0:ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ\nT;0;2:286:0:رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ\nT;0;2:286:0:عَلَيۡنَآ إِصۡرࣰا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا\nT;0;2:286:0:وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا\nT;2;2:286:2:وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ',
  '3;5;3;\nH;3\nB;3\nT;0;3:1:3:الٓمٓ¦3:2:3:ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ¦3:3:1:نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ\nT;0;3:3:2:بِٱلۡحَقِّ مُصَدِّقࣰا لِّمَا بَيۡنَ يَدَيۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ¦3:4:1:مِن\nT;0;3:4:0:قَبۡلُ هُدࣰى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ\nT;0;3:4:2:لَهُمۡ عَذَابࣱ شَدِيدࣱۗ وَٱللَّهُ عَزِيزࣱ ذُو ٱنتِقَامٍ¦3:5:1:إِنَّ ٱللَّهَ لَا يَخۡفَىٰ\nT;0;3:5:2:عَلَيۡهِ شَيۡءࣱ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ¦3:6:1:هُوَ ٱلَّذِي يُصَوِّرُكُمۡ\nT;0;3:6:2:فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦3:7:1:هُوَ\nT;0;3:7:0:ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتࣱ مُّحۡكَمَٰتٌ هُنَّ أُمُّ\nT;0;3:7:0:ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتࣱۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغࣱ فَيَتَّبِعُونَ\nT;0;3:7:0:مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ\nT;0;3:7:0:إِلَّا ٱللَّهُۗ وَٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلࣱّ مِّنۡ عِندِ\nT;0;3:7:2:رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ¦3:8:1:رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ\nT;0;3:8:2:إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ¦3:9:1:رَبَّنَآ\nT;0;3:9:2:إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوۡمࣲ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ',
  '3;5;3;21\nT;0;3:10:1:إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم\nT;0;3:10:2:مِّنَ ٱللَّهِ شَيۡـࣰٔاۖ وَأُوْلَٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ¦3:11:1:كَدَأۡبِ ءَالِ\nT;0;3:11:0:فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ\nT;0;3:11:2:بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ¦3:12:1:قُل لِّلَّذِينَ كَفَرُواْ\nT;0;3:12:2:سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ\nT;0;3:13:1:قَدۡ كَانَ لَكُمۡ ءَايَةࣱ فِي فِئَتَيۡنِ ٱلۡتَقَتَاۖ فِئَةࣱ تُقَٰتِلُ فِي\nT;0;3:13:0:سَبِيلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةࣱ يَرَوۡنَهُم مِّثۡلَيۡهِمۡ رَأۡيَ\nT;0;3:13:0:ٱلۡعَيۡنِۚ وَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ\nT;0;3:13:2:لَعِبۡرَةࣰ لِّأُوْلِي ٱلۡأَبۡصَٰرِ¦3:14:1:زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ\nT;0;3:14:0:مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ\nT;0;3:14:0:وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ\nT;0;3:14:2:مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ¦3:15:1:۞ قُلۡ\nT;0;3:15:0:أَؤُنَبِّئُكُم بِخَيۡرࣲ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ\nT;0;3:15:0:جَنَّٰتࣱ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجࣱ\nT;0;3:15:2:مُّطَهَّرَةࣱ وَرِضۡوَٰنࣱ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ',
  '3;6;0;\nT;0;3:16:1:ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا\nT;0;3:16:2:وَقِنَا عَذَابَ ٱلنَّارِ¦3:17:1:ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلۡقَٰنِتِينَ\nT;0;3:17:2:وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ¦3:18:1:شَهِدَ ٱللَّهُ\nT;0;3:18:0:أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا\nT;0;3:18:2:بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦3:19:1:إِنَّ ٱلدِّينَ\nT;0;3:19:0:عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ\nT;0;3:19:0:إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ\nT;0;3:19:2:بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ¦3:20:1:فَإِنۡ حَآجُّوكَ\nT;0;3:20:0:فَقُلۡ أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ\nT;0;3:20:0:ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ\nT;0;3:20:2:وَّإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ\nT;0;3:21:1:إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ\nT;0;3:21:0:بِغَيۡرِ حَقࣲّ وَيَقۡتُلُونَ ٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ\nT;0;3:21:2:ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ¦3:22:1:أُوْلَٰٓئِكَ ٱلَّذِينَ حَبِطَتۡ\nT;0;3:22:2:أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ',
  '3;6;0;\nT;0;3:23:1:أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبࣰا مِّنَ ٱلۡكِتَٰبِ يُدۡعَوۡنَ إِلَىٰ كِتَٰبِ\nT;0;3:23:2:ٱللَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُمَّ يَتَوَلَّىٰ فَرِيقࣱ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ\nT;0;3:24:1:ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامࣰا مَّعۡدُودَٰتࣲۖ\nT;0;3:24:2:وَغَرَّهُمۡ فِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ¦3:25:1:فَكَيۡفَ إِذَا جَمَعۡنَٰهُمۡ\nT;0;3:25:0:لِيَوۡمࣲ لَّا رَيۡبَ فِيهِ وَوُفِّيَتۡ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ\nT;0;3:25:2:لَا يُظۡلَمُونَ¦3:26:1:قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن\nT;0;3:26:0:تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن\nT;0;3:26:2:تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ¦3:27:1:تُولِجُ ٱلَّيۡلَ\nT;0;3:27:0:فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ\nT;0;3:27:2:وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابࣲ\nT;0;3:28:1:لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ\nT;0;3:28:0:وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ\nT;0;3:28:2:تُقَىٰةࣰۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ¦3:29:1:قُلۡ\nT;0;3:29:0:إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ\nT;0;3:29:2:مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ',
  '3;6;0;22\nT;0;3:30:1:يَوۡمَ تَجِدُ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ مِنۡ خَيۡرࣲ مُّحۡضَرࣰا وَمَا عَمِلَتۡ\nT;0;3:30:0:مِن سُوٓءࣲ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدࣰاۗ وَيُحَذِّرُكُمُ ٱللَّهُ\nT;0;3:30:2:نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ¦3:31:1:قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ\nT;0;3:31:0:فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورࣱ\nT;0;3:31:2:رَّحِيمࣱ¦3:32:1:قُلۡ أَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ\nT;0;3:32:2:ٱلۡكَٰفِرِينَ¦3:33:1:۞ إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحࣰا وَءَالَ إِبۡرَٰهِيمَ\nT;0;3:33:2:وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ¦3:34:1:ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضࣲۗ وَٱللَّهُ\nT;0;3:34:2:سَمِيعٌ عَلِيمٌ¦3:35:1:إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ\nT;0;3:35:2:مَا فِي بَطۡنِي مُحَرَّرࣰا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\nT;0;3:36:1:فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ\nT;0;3:36:0:وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ\nT;0;3:36:2:وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ¦3:37:1:فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ\nT;0;3:37:0:حَسَنࣲ وَأَنۢبَتَهَا نَبَاتًا حَسَنࣰا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا\nT;0;3:37:0:زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقࣰاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ\nT;0;3:37:2:قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ',
  '3;6;1;\nT;0;3:38:1:هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةࣰ\nT;0;3:38:2:طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ¦3:39:1:فَنَادَتۡهُ ٱلۡمَلَٰٓئِكَةُ وَهُوَ قَآئِمࣱ\nT;0;3:39:0:يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةࣲ\nT;0;3:39:2:مِّنَ ٱللَّهِ وَسَيِّدࣰا وَحَصُورࣰا وَنَبِيࣰّا مِّنَ ٱلصَّٰلِحِينَ¦3:40:1:قَالَ رَبِّ\nT;0;3:40:0:أَنَّىٰ يَكُونُ لِي غُلَٰمࣱ وَقَدۡ بَلَغَنِيَ ٱلۡكِبَرُ وَٱمۡرَأَتِي عَاقِرࣱۖ قَالَ\nT;0;3:40:2:كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ مَا يَشَآءُ¦3:41:1:قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةࣰۖ\nT;0;3:41:0:قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزࣰاۗ وَٱذۡكُر\nT;0;3:41:2:رَّبَّكَ كَثِيرࣰا وَسَبِّحۡ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ¦3:42:1:وَإِذۡ قَالَتِ\nT;0;3:42:0:ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ\nT;0;3:42:2:عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ¦3:43:1:يَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي\nT;0;3:43:2:وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ¦3:44:1:ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۚ\nT;0;3:44:0:وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ\nT;0;3:44:2:وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ¦3:45:1:إِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ\nT;0;3:45:0:يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةࣲ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ عِيسَى\nT;0;3:45:2:ٱبۡنُ مَرۡيَمَ وَجِيهࣰا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ',
  '3;6;1;23\nT;0;3:46:3:وَيُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلࣰا وَمِنَ ٱلصَّٰلِحِينَ\nT;0;3:47:1:قَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدࣱ وَلَمۡ يَمۡسَسۡنِي بَشَرࣱۖ قَالَ كَذَٰلِكِ\nT;0;3:47:2:ٱللَّهُ يَخۡلُقُ مَا يَشَآءُۚ إِذَا قَضَىٰٓ أَمۡرࣰا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ\nT;0;3:48:3:وَيُعَلِّمُهُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ\nT;0;3:49:1:وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةࣲ مِّن\nT;0;3:49:0:رَّبِّكُمۡ أَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ\nT;0;3:49:0:فِيهِ فَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ\nT;0;3:49:0:وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ\nT;0;3:49:2:فِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ\nT;0;3:50:1:وَمُصَدِّقࣰا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم\nT;0;3:50:0:بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ وَجِئۡتُكُم بِـَٔايَةࣲ مِّن رَّبِّكُمۡ\nT;0;3:50:2:فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ¦3:51:1:إِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ\nT;0;3:51:2:هَٰذَا صِرَٰطࣱ مُّسۡتَقِيمࣱ¦3:52:1:۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ\nT;0;3:52:0:ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ\nT;0;3:52:2:أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ',
  '3;6;2;\nT;0;3:53:1:رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ\nT;0;3:53:2:ٱلشَّٰهِدِينَ¦3:54:3:وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ\nT;0;3:55:1:إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ\nT;0;3:55:0:مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ\nT;0;3:55:0:كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ\nT;0;3:55:2:بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ¦3:56:1:فَأَمَّا ٱلَّذِينَ كَفَرُواْ\nT;0;3:56:0:فَأُعَذِّبُهُمۡ عَذَابࣰا شَدِيدࣰا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم\nT;0;3:56:2:مِّن نَّٰصِرِينَ¦3:57:1:وَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ\nT;0;3:57:2:فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ¦3:58:1:ذَٰلِكَ نَتۡلُوهُ\nT;0;3:58:2:عَلَيۡكَ مِنَ ٱلۡأٓيَٰتِ وَٱلذِّكۡرِ ٱلۡحَكِيمِ¦3:59:1:إِنَّ مَثَلَ\nT;0;3:59:0:عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابࣲ ثُمَّ قَالَ لَهُۥ\nT;0;3:59:2:كُن فَيَكُونُ¦3:60:3:ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ\nT;0;3:61:1:فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ\nT;0;3:61:0:نَدۡعُ أَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا\nT;0;3:61:2:وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ',
  '3;6;2;\nT;0;3:62:1:إِنَّ هَٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ\nT;0;3:62:2:ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦3:63:3:فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ عَلِيمُۢ بِٱلۡمُفۡسِدِينَ\nT;0;3:64:1:قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةࣲ سَوَآءِۭ بَيۡنَنَا\nT;0;3:64:0:وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـࣰٔا وَلَا يَتَّخِذَ\nT;0;3:64:0:بَعۡضُنَا بَعۡضًا أَرۡبَابࣰا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ\nT;0;3:64:2:بِأَنَّا مُسۡلِمُونَ¦3:65:1:يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ\nT;0;3:65:2:وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ أَفَلَا تَعۡقِلُونَ\nT;0;3:66:1:هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ عِلۡمࣱ فَلِمَ\nT;0;3:66:0:تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمࣱۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ\nT;0;3:66:2:لَا تَعۡلَمُونَ¦3:67:1:مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيࣰّا وَلَا نَصۡرَانِيࣰّا\nT;0;3:67:2:وَلَٰكِن كَانَ حَنِيفࣰا مُّسۡلِمࣰا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ\nT;0;3:68:1:إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ\nT;0;3:68:2:ءَامَنُواْۗ وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ¦3:69:1:وَدَّت طَّآئِفَةࣱ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ\nT;0;3:69:2:لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ¦3:70:1:يَٰٓأَهۡلَ\nT;0;3:70:2:ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ',
  '3;6;2;24\nT;0;3:71:1:يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ\nT;0;3:71:2:وَأَنتُمۡ تَعۡلَمُونَ¦3:72:1:وَقَالَت طَّآئِفَةࣱ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ ءَامِنُواْ\nT;0;3:72:0:بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ\nT;0;3:72:2:لَعَلَّهُمۡ يَرۡجِعُونَ¦3:73:1:وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ\nT;0;3:73:0:ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدࣱ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ\nT;0;3:73:0:عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ\nT;0;3:73:2:وَٰسِعٌ عَلِيمࣱ¦3:74:1:يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ\nT;0;3:74:2:ٱلۡعَظِيمِ¦3:75:1:۞ وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارࣲ\nT;0;3:75:0:يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارࣲ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ\nT;0;3:75:0:إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمࣰاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي\nT;0;3:75:2:ٱلۡأُمِّيِّـۧنَ سَبِيلࣱ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ\nT;0;3:76:3:بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ\nT;0;3:77:1:إِنَّ ٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنࣰا قَلِيلًا\nT;0;3:77:0:أُوْلَٰٓئِكَ لَا خَلَٰقَ لَهُمۡ فِي ٱلۡأٓخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ\nT;0;3:77:2:إِلَيۡهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمࣱ',
  '3;6;3;\nT;0;3:78:1:وَإِنَّ مِنۡهُمۡ لَفَرِيقࣰا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ\nT;0;3:78:0:مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ\nT;0;3:78:0:عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ\nT;0;3:78:2:وَهُمۡ يَعۡلَمُونَ¦3:79:1:مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ\nT;0;3:79:0:وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَادࣰا لِّي مِن\nT;0;3:79:0:دُونِ ٱللَّهِ وَلَٰكِن كُونُواْ رَبَّٰنِيِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ\nT;0;3:79:2:ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ¦3:80:1:وَلَا يَأۡمُرَكُمۡ أَن\nT;0;3:80:0:تَتَّخِذُواْ ٱلۡمَلَٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرۡبَابًاۚ أَيَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ\nT;0;3:80:2:إِذۡ أَنتُم مُّسۡلِمُونَ¦3:81:1:وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم\nT;0;3:81:0:مِّن كِتَٰبࣲ وَحِكۡمَةࣲ ثُمَّ جَآءَكُمۡ رَسُولࣱ مُّصَدِّقࣱ لِّمَا\nT;0;3:81:0:مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ\nT;0;3:81:0:عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم\nT;0;3:81:2:مِّنَ ٱلشَّٰهِدِينَ¦3:82:1:فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ\nT;0;3:82:2:ٱلۡفَٰسِقُونَ¦3:83:1:أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي\nT;0;3:83:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعࣰا وَكَرۡهࣰا وَإِلَيۡهِ يُرۡجَعُونَ',
  '3;6;3;\nT;0;3:84:1:قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ\nT;0;3:84:0:وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ\nT;0;3:84:0:وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدࣲ مِّنۡهُمۡ\nT;0;3:84:2:وَنَحۡنُ لَهُۥ مُسۡلِمُونَ¦3:85:1:وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينࣰا فَلَن\nT;0;3:85:2:يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ¦3:86:1:كَيۡفَ\nT;0;3:86:0:يَهۡدِي ٱللَّهُ قَوۡمࣰا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ\nT;0;3:86:0:ٱلرَّسُولَ حَقࣱّ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ\nT;0;3:86:2:ٱلظَّٰلِمِينَ¦3:87:1:أُوْلَٰٓئِكَ جَزَآؤُهُمۡ أَنَّ عَلَيۡهِمۡ لَعۡنَةَ ٱللَّهِ\nT;0;3:87:2:وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ¦3:88:1:خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ\nT;0;3:88:2:عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ¦3:89:1:إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ\nT;0;3:89:2:بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ¦3:90:1:إِنَّ ٱلَّذِينَ\nT;0;3:90:0:كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرࣰا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ\nT;0;3:90:2:وَأُوْلَٰٓئِكَ هُمُ ٱلضَّآلُّونَ¦3:91:1:إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ\nT;0;3:91:0:كُفَّارࣱ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبࣰا وَلَوِ\nT;0;3:91:2:ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمࣱ وَمَا لَهُم مِّن نَّٰصِرِينَ',
  '4;6;3;25\nT;0;3:92:1:لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءࣲ\nT;0;3:92:2:فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمࣱ¦3:93:1:۞ كُلُّ ٱلطَّعَامِ كَانَ حِلࣰّا لِّبَنِيٓ\nT;0;3:93:0:إِسۡرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ\nT;0;3:93:2:ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ\nT;0;3:94:1:فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَٰلِكَ فَأُوْلَٰٓئِكَ\nT;0;3:94:2:هُمُ ٱلظَّٰلِمُونَ¦3:95:1:قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُواْ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفࣰاۖ\nT;0;3:95:2:وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ¦3:96:1:إِنَّ أَوَّلَ بَيۡتࣲ وُضِعَ لِلنَّاسِ لَلَّذِي\nT;0;3:96:2:بِبَكَّةَ مُبَارَكࣰا وَهُدࣰى لِّلۡعَٰلَمِينَ¦3:97:1:فِيهِ ءَايَٰتُۢ بَيِّنَٰتࣱ مَّقَامُ\nT;0;3:97:0:إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنࣰاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ\nT;0;3:97:2:مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلࣰاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ\nT;0;3:98:1:قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ\nT;0;3:98:2:عَلَىٰ مَا تَعۡمَلُونَ¦3:99:1:قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَصُدُّونَ عَن\nT;0;3:99:0:سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجࣰا وَأَنتُمۡ شُهَدَآءُۗ وَمَا ٱللَّهُ\nT;0;3:99:2:بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ¦3:100:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقࣰا\nT;0;3:100:2:مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ',
  '4;7;0;\nT;0;3:101:1:وَكَيۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَٰتُ ٱللَّهِ وَفِيكُمۡ\nT;0;3:101:2:رَسُولُهُۥۗ وَمَن يَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ\nT;0;3:102:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم\nT;0;3:102:2:مُّسۡلِمُونَ¦3:103:1:وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعࣰا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ\nT;0;3:103:0:نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءࣰ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ\nT;0;3:103:0:فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنࣰا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةࣲ مِّنَ\nT;0;3:103:0:ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ\nT;0;3:103:2:تَهۡتَدُونَ¦3:104:1:وَلۡتَكُن مِّنكُمۡ أُمَّةࣱ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ\nT;0;3:104:2:بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ\nT;0;3:105:1:وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ\nT;0;3:105:2:وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمࣱ¦3:106:1:يَوۡمَ تَبۡيَضُّ وُجُوهࣱ وَتَسۡوَدُّ\nT;0;3:106:0:وُجُوهࣱۚ فَأَمَّا ٱلَّذِينَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ\nT;0;3:106:2:فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ¦3:107:1:وَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ\nT;0;3:107:2:وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ¦3:108:1:تِلۡكَ ءَايَٰتُ\nT;0;3:108:2:ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمࣰا لِّلۡعَٰلَمِينَ',
  '4;7;0;26\nT;0;3:109:3:وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ\nT;0;3:110:1:كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ\nT;0;3:110:0:وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ\nT;0;3:110:0:ٱلۡكِتَٰبِ لَكَانَ خَيۡرࣰا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ\nT;0;3:110:2:ٱلۡفَٰسِقُونَ¦3:111:1:لَن يَضُرُّوكُمۡ إِلَّآ أَذࣰىۖ وَإِن يُقَٰتِلُوكُمۡ\nT;0;3:111:2:يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ¦3:112:1:ضُرِبَتۡ عَلَيۡهِمُ\nT;0;3:112:0:ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلࣲ مِّنَ ٱللَّهِ وَحَبۡلࣲ مِّنَ ٱلنَّاسِ\nT;0;3:112:0:وَبَآءُو بِغَضَبࣲ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ\nT;0;3:112:0:بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ\nT;0;3:112:2:بِغَيۡرِ حَقࣲّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ¦3:113:1:۞ لَيۡسُواْ\nT;0;3:113:0:سَوَآءࣰۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةࣱ قَآئِمَةࣱ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ\nT;0;3:113:2:ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ¦3:114:1:يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ\nT;0;3:114:0:ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ\nT;0;3:114:2:وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ¦3:115:1:وَمَا\nT;0;3:115:2:يَفۡعَلُواْ مِنۡ خَيۡرࣲ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ',
  '4;7;1;\nT;0;3:116:1:إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ\nT;0;3:116:2:ٱللَّهِ شَيۡـࣰٔاۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ\nT;0;3:117:1:مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحࣲ فِيهَا\nT;0;3:117:0:صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمࣲ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا\nT;0;3:117:2:ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنۡ أَنفُسَهُمۡ يَظۡلِمُونَ¦3:118:1:يَٰٓأَيُّهَا ٱلَّذِينَ\nT;0;3:118:0:ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةࣰ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالࣰا\nT;0;3:118:0:وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي\nT;0;3:118:2:صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ\nT;0;3:119:1:هَٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ\nT;0;3:119:0:كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ\nT;0;3:119:0:ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ\nT;0;3:119:2:ٱلصُّدُورِ¦3:120:1:إِن تَمۡسَسۡكُمۡ حَسَنَةࣱ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ\nT;0;3:120:0:سَيِّئَةࣱ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ\nT;0;3:120:2:شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطࣱ¦3:121:1:وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ\nT;0;3:121:2:تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ',
  '4;7;1;\nT;0;3:122:1:إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ\nT;0;3:122:2:فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ¦3:123:1:وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرࣲ وَأَنتُمۡ أَذِلَّةࣱۖ\nT;0;3:123:2:فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ¦3:124:1:إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ\nT;0;3:124:0:أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفࣲ مِّنَ ٱلۡمَلَٰٓئِكَةِ\nT;0;3:124:2:مُنزَلِينَ¦3:125:1:بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ\nT;0;3:125:2:هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفࣲ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُسَوِّمِينَ\nT;0;3:126:1:وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ\nT;0;3:126:2:وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ¦3:127:1:لِيَقۡطَعَ طَرَفࣰا\nT;0;3:127:2:مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ\nT;0;3:128:1:لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ\nT;0;3:128:2:ظَٰلِمُونَ¦3:129:1:وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن\nT;0;3:129:2:يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورࣱ رَّحِيمࣱ¦3:130:1:يَٰٓأَيُّهَا\nT;0;3:130:0:ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفࣰا مُّضَٰعَفَةࣰۖ\nT;0;3:130:2:وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ¦3:131:1:وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ\nT;0;3:131:2:لِلۡكَٰفِرِينَ¦3:132:3:وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ',
  '4;7;2;27\nT;0;3:133:1:۞ وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا\nT;0;3:133:2:ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ¦3:134:1:ٱلَّذِينَ يُنفِقُونَ\nT;0;3:134:0:فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ\nT;0;3:134:2:عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ¦3:135:1:وَٱلَّذِينَ إِذَا فَعَلُواْ\nT;0;3:135:0:فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ\nT;0;3:135:0:لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا\nT;0;3:135:2:فَعَلُواْ وَهُمۡ يَعۡلَمُونَ¦3:136:1:أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةࣱ مِّن\nT;0;3:136:0:رَّبِّهِمۡ وَجَنَّٰتࣱ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ\nT;0;3:136:2:أَجۡرُ ٱلۡعَٰمِلِينَ¦3:137:1:قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنࣱ فَسِيرُواْ\nT;0;3:137:2:فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ\nT;0;3:138:3:هَٰذَا بَيَانࣱ لِّلنَّاسِ وَهُدࣰى وَمَوۡعِظَةࣱ لِّلۡمُتَّقِينَ\nT;0;3:139:3:وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ\nT;0;3:140:1:إِن يَمۡسَسۡكُمۡ قَرۡحࣱ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحࣱ مِّثۡلُهُۥۚ وَتِلۡكَ\nT;0;3:140:0:ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ\nT;0;3:140:2:وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ',
  '4;7;2;\nT;0;3:141:3:وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَمۡحَقَ ٱلۡكَٰفِرِينَ¦3:142:1:أَمۡ\nT;0;3:142:0:حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ\nT;0;3:142:2:مِنكُمۡ وَيَعۡلَمَ ٱلصَّٰبِرِينَ¦3:143:1:وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن\nT;0;3:143:2:قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَيۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ¦3:144:1:وَمَا مُحَمَّدٌ\nT;0;3:144:0:إِلَّا رَسُولࣱ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ\nT;0;3:144:0:ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ\nT;0;3:144:2:ٱللَّهَ شَيۡـࣰٔاۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّٰكِرِينَ¦3:145:1:وَمَا كَانَ\nT;0;3:145:0:لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبࣰا مُّؤَجَّلࣰاۗ وَمَن يُرِدۡ\nT;0;3:145:0:ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ\nT;0;3:145:2:وَسَنَجۡزِي ٱلشَّٰكِرِينَ¦3:146:1:وَكَأَيِّن مِّن نَّبِيࣲّ قَٰتَلَ مَعَهُۥ\nT;0;3:146:0:رِبِّيُّونَ كَثِيرࣱ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ\nT;0;3:146:2:وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ¦3:147:1:وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن\nT;0;3:147:0:قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا\nT;0;3:147:2:وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ¦3:148:1:فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ\nT;0;3:148:2:ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ',
  '4;7;2;28\nT;0;3:149:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ\nT;0;3:149:2:يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ\nT;0;3:150:3:بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَيۡرُ ٱلنَّٰصِرِينَ¦3:151:1:سَنُلۡقِي\nT;0;3:151:0:فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ\nT;0;3:151:0:مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنࣰاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ\nT;0;3:151:2:مَثۡوَى ٱلظَّٰلِمِينَ¦3:152:1:وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ\nT;0;3:152:0:وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ\nT;0;3:152:0:وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم\nT;0;3:152:0:مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن\nT;0;3:152:0:يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ\nT;0;3:152:2:وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ\nT;0;3:153:1:۞ إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدࣲ\nT;0;3:153:0:وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ\nT;0;3:153:0:غَمَّۢا بِغَمࣲّ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا\nT;0;3:153:2:مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ',
  '4;7;3;\nT;0;3:154:1:ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةࣰ نُّعَاسࣰا يَغۡشَىٰ طَآئِفَةࣰ\nT;0;3:154:0:مِّنكُمۡۖ وَطَآئِفَةࣱ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ\nT;0;3:154:0:ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءࣲۗ\nT;0;3:154:0:قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ\nT;0;3:154:0:يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءࣱ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ\nT;0;3:154:0:فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ\nT;0;3:154:0:وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ\nT;0;3:154:2:وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ¦3:155:1:إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ\nT;0;3:155:0:يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ\nT;0;3:155:2:مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمࣱ¦3:156:1:يَٰٓأَيُّهَا\nT;0;3:156:0:ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا\nT;0;3:156:0:ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزࣰّى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ\nT;0;3:156:0:وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةࣰ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ\nT;0;3:156:2:وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرࣱ¦3:157:1:وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ\nT;0;3:157:2:ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةࣱ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرࣱ مِّمَّا يَجۡمَعُونَ',
  '4;7;3;\nT;0;3:158:3:وَلَئِن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ¦3:159:1:فَبِمَا رَحۡمَةࣲ مِّنَ ٱللَّهِ\nT;0;3:159:0:لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ\nT;0;3:159:0:فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ\nT;0;3:159:2:فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ¦3:160:1:إِن يَنصُرۡكُمُ ٱللَّهُ\nT;0;3:160:0:فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ\nT;0;3:160:2:بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ¦3:161:1:وَمَا كَانَ لِنَبِيٍّ أَن\nT;0;3:161:0:يَغُلَّۚ وَمَن يَغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ ٱلۡقِيَٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ\nT;0;3:161:2:نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ¦3:162:1:أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ ٱللَّهِ\nT;0;3:162:2:كَمَنۢ بَآءَ بِسَخَطࣲ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ\nT;0;3:163:3:هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ¦3:164:1:لَقَدۡ\nT;0;3:164:0:مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولࣰا مِّنۡ أَنفُسِهِمۡ\nT;0;3:164:0:يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ\nT;0;3:164:2:وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلࣲ مُّبِينٍ¦3:165:1:أَوَلَمَّآ\nT;0;3:165:0:أَصَٰبَتۡكُم مُّصِيبَةࣱ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ\nT;0;3:165:2:قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ',
  '4;7;3;29\nT;0;3:166:3:وَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِيَعۡلَمَ ٱلۡمُؤۡمِنِينَ\nT;0;3:167:1:وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ وَقِيلَ لَهُمۡ تَعَالَوۡاْ قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ\nT;0;3:167:0:أَوِ ٱدۡفَعُواْۖ قَالُواْ لَوۡ نَعۡلَمُ قِتَالࣰا لَّٱتَّبَعۡنَٰكُمۡۗ هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ\nT;0;3:167:0:أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ\nT;0;3:167:2:وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ¦3:168:1:ٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ وَقَعَدُواْ\nT;0;3:168:0:لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن\nT;0;3:168:2:كُنتُمۡ صَٰدِقِينَ¦3:169:1:وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ\nT;0;3:169:2:أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ¦3:170:1:فَرِحِينَ بِمَآ ءَاتَىٰهُمُ\nT;0;3:170:0:ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم\nT;0;3:170:2:مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ¦3:171:1:۞ يَسۡتَبۡشِرُونَ\nT;0;3:171:0:بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ\nT;0;3:171:2:ٱلۡمُؤۡمِنِينَ¦3:172:1:ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ\nT;0;3:172:2:ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ\nT;0;3:173:1:ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ\nT;0;3:173:2:فَزَادَهُمۡ إِيمَٰنࣰا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ',
  '4;8;0;\nT;0;3:174:1:فَٱنقَلَبُواْ بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءࣱ وَٱتَّبَعُواْ\nT;0;3:174:2:رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ¦3:175:1:إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ\nT;0;3:175:2:يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ\nT;0;3:176:1:وَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ\nT;0;3:176:0:شَيۡـࣰٔاۚ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظࣰّا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ\nT;0;3:176:2:عَظِيمٌ¦3:177:1:إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ ٱللَّهَ\nT;0;3:177:2:شَيۡـࣰٔاۖ وَلَهُمۡ عَذَابٌ أَلِيمࣱ¦3:178:1:وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ أَنَّمَا\nT;0;3:178:0:نُمۡلِي لَهُمۡ خَيۡرࣱ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمࣰاۖ وَلَهُمۡ\nT;0;3:178:2:عَذَابࣱ مُّهِينࣱ¦3:179:1:مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ\nT;0;3:179:0:عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ\nT;0;3:179:0:عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ\nT;0;3:179:2:وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمࣱ¦3:180:1:وَلَا يَحۡسَبَنَّ\nT;0;3:180:0:ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرࣰا لَّهُمۖ\nT;0;3:180:0:بَلۡ هُوَ شَرࣱّ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ\nT;0;3:180:2:مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ',
  '4;8;0;30\nT;0;3:181:1:لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرࣱ وَنَحۡنُ أَغۡنِيَآءُۘ\nT;0;3:181:0:سَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقࣲّ وَنَقُولُ\nT;0;3:181:2:ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ¦3:182:1:ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ\nT;0;3:182:2:وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّامࣲ لِّلۡعَبِيدِ¦3:183:1:ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ\nT;0;3:183:0:عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانࣲ\nT;0;3:183:0:تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلࣱ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ\nT;0;3:183:2:وَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ\nT;0;3:184:1:فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلࣱ مِّن قَبۡلِكَ جَآءُو\nT;0;3:184:2:بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ¦3:185:1:كُلُّ نَفۡسࣲ\nT;0;3:185:0:ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ\nT;0;3:185:0:فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا\nT;0;3:185:2:ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ¦3:186:1:۞ لَتُبۡلَوُنَّ فِيٓ\nT;0;3:186:0:أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ\nT;0;3:186:0:ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذࣰى كَثِيرࣰاۚ\nT;0;3:186:2:وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ',
  '4;8;1;\nT;0;3:187:1:وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ\nT;0;3:187:0:وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡاْ بِهِۦ ثَمَنࣰا\nT;0;3:187:2:قَلِيلࣰاۖ فَبِئۡسَ مَا يَشۡتَرُونَ¦3:188:1:لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ بِمَآ\nT;0;3:188:0:أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم\nT;0;3:188:2:بِمَفَازَةࣲ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِيمࣱ¦3:189:1:وَلِلَّهِ مُلۡكُ\nT;0;3:189:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ¦3:190:1:إِنَّ فِي\nT;0;3:190:0:خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتࣲ\nT;0;3:190:2:لِّأُوْلِي ٱلۡأَلۡبَٰبِ¦3:191:1:ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمࣰا وَقُعُودࣰا\nT;0;3:191:0:وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ\nT;0;3:191:2:رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلࣰا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ\nT;0;3:192:1:رَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّٰلِمِينَ مِنۡ\nT;0;3:192:2:أَنصَارࣲ¦3:193:1:رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيࣰا يُنَادِي لِلۡإِيمَٰنِ أَنۡ\nT;0;3:193:0:ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا\nT;0;3:193:2:سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ¦3:194:1:رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ\nT;0;3:194:2:رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ',
  '4;8;1;\nT;0;3:195:1:فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلࣲ مِّنكُم مِّن\nT;0;3:195:0:ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضࣲۖ فَٱلَّذِينَ هَاجَرُواْ\nT;0;3:195:0:وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ\nT;0;3:195:0:لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّٰتࣲ تَجۡرِي\nT;0;3:195:0:مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابࣰا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ\nT;0;3:195:2:حُسۡنُ ٱلثَّوَابِ¦3:196:1:لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي\nT;0;3:196:2:ٱلۡبِلَٰدِ¦3:197:3:مَتَٰعࣱ قَلِيلࣱ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ\nT;0;3:198:1:لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّٰتࣱ تَجۡرِي\nT;0;3:198:0:مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلࣰا مِّنۡ عِندِ\nT;0;3:198:2:ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرࣱ لِّلۡأَبۡرَارِ¦3:199:1:وَإِنَّ مِنۡ أَهۡلِ\nT;0;3:199:0:ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ\nT;0;3:199:0:إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنࣰا\nT;0;3:199:0:قَلِيلًاۚ أُوْلَٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ\nT;0;3:199:2:سَرِيعُ ٱلۡحِسَابِ¦3:200:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ\nT;2;3:200:2:وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ',
  '4;8;2;31\nH;4\nB;4\nT;0;4:1:1:يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسࣲ وَٰحِدَةࣲ وَخَلَقَ مِنۡهَا\nT;0;4:1:0:زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالࣰا كَثِيرࣰا وَنِسَآءࣰۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ\nT;0;4:1:2:وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبࣰا¦4:2:1:وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ\nT;0;4:2:2:ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبࣰا كَبِيرࣰا\nT;0;4:3:1:وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ\nT;0;4:3:0:مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ\nT;0;4:3:2:ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ¦4:4:1:وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةࣰۚ فَإِن طِبۡنَ\nT;0;4:4:2:لَكُمۡ عَن شَيۡءࣲ مِّنۡهُ نَفۡسࣰا فَكُلُوهُ هَنِيٓـࣰٔا مَّرِيٓـࣰٔا¦4:5:1:وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ\nT;0;4:5:0:أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمࣰا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ\nT;0;4:5:2:قَوۡلࣰا مَّعۡرُوفࣰا¦4:6:1:وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ\nT;0;4:6:0:رُشۡدࣰا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافࣰا وَبِدَارًا أَن يَكۡبَرُواْۚ\nT;0;4:6:0:وَمَن كَانَ غَنِيࣰّا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرࣰا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ\nT;0;4:6:2:فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبࣰا',
  '4;8;2;\nT;0;4:7:1:لِّلرِّجَالِ نَصِيبࣱ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبࣱ\nT;0;4:7:0:مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبࣰا\nT;0;4:7:2:مَّفۡرُوضࣰا¦4:8:1:وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ\nT;0;4:8:2:وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلࣰا مَّعۡرُوفࣰا\nT;0;4:9:1:وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةࣰ ضِعَٰفًا\nT;0;4:9:2:خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلࣰا سَدِيدًا¦4:10:1:إِنَّ\nT;0;4:10:0:ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي\nT;0;4:10:2:بُطُونِهِمۡ نَارࣰاۖ وَسَيَصۡلَوۡنَ سَعِيرࣰا¦4:11:1:يُوصِيكُمُ ٱللَّهُ فِيٓ\nT;0;4:11:0:أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءࣰ\nT;0;4:11:0:فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةࣰ فَلَهَا\nT;0;4:11:0:ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدࣲ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن\nT;0;4:11:0:كَانَ لَهُۥ وَلَدࣱۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدࣱ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن\nT;0;4:11:0:كَانَ لَهُۥٓ إِخۡوَةࣱ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةࣲ يُوصِي بِهَآ\nT;0;4:11:0:أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ\nT;0;4:11:2:نَفۡعࣰاۚ فَرِيضَةࣰ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمࣰا',
  '4;8;3;32\nT;0;4:12:1:۞ وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن\nT;0;4:12:0:لَّهُنَّ وَلَدࣱۚ فَإِن كَانَ لَهُنَّ وَلَدࣱ فَلَكُمُ ٱلرُّبُعُ مِمَّا\nT;0;4:12:0:تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةࣲ يُوصِينَ بِهَآ أَوۡ دَيۡنࣲۚ\nT;0;4:12:0:وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدࣱۚ\nT;0;4:12:0:فَإِن كَانَ لَكُمۡ وَلَدࣱ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ\nT;0;4:12:0:مِّنۢ بَعۡدِ وَصِيَّةࣲ تُوصُونَ بِهَآ أَوۡ دَيۡنࣲۗ وَإِن كَانَ\nT;0;4:12:0:رَجُلࣱ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةࣱ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتࣱ فَلِكُلِّ\nT;0;4:12:0:وَٰحِدࣲ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ\nT;0;4:12:0:فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةࣲ يُوصَىٰ\nT;0;4:12:0:بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرࣲّۚ وَصِيَّةࣰ مِّنَ ٱللَّهِۗ وَٱللَّهُ\nT;0;4:12:2:عَلِيمٌ حَلِيمࣱ¦4:13:1:تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ\nT;0;4:13:0:وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا\nT;0;4:13:2:ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\nT;0;4:14:1:وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ\nT;0;4:14:2:يُدۡخِلۡهُ نَارًا خَٰلِدࣰا فِيهَا وَلَهُۥ عَذَابࣱ مُّهِينࣱ',
  '4;8;3;\nT;0;4:15:1:وَٱلَّٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ\nT;0;4:15:0:أَرۡبَعَةࣰ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ\nT;0;4:15:2:حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلࣰا\nT;0;4:16:1:وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا\nT;0;4:16:2:فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابࣰا رَّحِيمًا\nT;0;4:17:1:إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةࣲ\nT;0;4:17:0:ثُمَّ يَتُوبُونَ مِن قَرِيبࣲ فَأُوْلَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ\nT;0;4:17:2:وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمࣰا¦4:18:1:وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ\nT;0;4:18:0:يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ\nT;0;4:18:0:قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌۚ\nT;0;4:18:2:أُوْلَٰٓئِكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمࣰا¦4:19:1:يَٰٓأَيُّهَا ٱلَّذِينَ\nT;0;4:19:0:ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهࣰاۖ وَلَا تَعۡضُلُوهُنَّ\nT;0;4:19:0:لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةࣲ\nT;0;4:19:0:مُّبَيِّنَةࣲۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ\nT;0;4:19:2:أَن تَكۡرَهُواْ شَيۡـࣰٔا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرࣰا كَثِيرࣰا',
  '4;8;3;\nT;0;4:20:1:وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجࣲ مَّكَانَ زَوۡجࣲ وَءَاتَيۡتُمۡ\nT;0;4:20:0:إِحۡدَىٰهُنَّ قِنطَارࣰا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ\nT;0;4:20:2:بُهۡتَٰنࣰا وَإِثۡمࣰا مُّبِينࣰا¦4:21:1:وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ\nT;0;4:21:2:بَعۡضُكُمۡ إِلَىٰ بَعۡضࣲ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظࣰا\nT;0;4:22:1:وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ\nT;0;4:22:0:إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةࣰ وَمَقۡتࣰا وَسَآءَ\nT;0;4:22:2:سَبِيلًا¦4:23:1:حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ\nT;0;4:23:0:وَأَخَوَٰتُكُمۡ وَعَمَّٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ\nT;0;4:23:0:ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِيٓ أَرۡضَعۡنَكُمۡ\nT;0;4:23:0:وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ\nT;0;4:23:0:وَرَبَٰٓئِبُكُمُ ٱلَّٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ\nT;0;4:23:0:ٱلَّٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا\nT;0;4:23:0:جُنَاحَ عَلَيۡكُمۡ وَحَلَٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ\nT;0;4:23:0:أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا\nT;0;4:23:2:مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِيمࣰا',
  '5;9;0;33\nT;0;4:24:1:۞ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ\nT;0;4:24:0:كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ\nT;0;4:24:0:بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ\nT;0;4:24:0:مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةࣰۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا\nT;0;4:24:0:تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا\nT;0;4:24:2:حَكِيمࣰا¦4:25:1:وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ\nT;0;4:25:0:ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن\nT;0;4:25:0:فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم\nT;0;4:25:0:مِّنۢ بَعۡضࣲۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ\nT;0;4:25:0:بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتࣲ وَلَا مُتَّخِذَٰتِ\nT;0;4:25:0:أَخۡدَانࣲۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةࣲ فَعَلَيۡهِنَّ نِصۡفُ\nT;0;4:25:0:مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ\nT;0;4:25:2:مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرࣱ لَّكُمۡۗ وَٱللَّهُ غَفُورࣱ رَّحِيمࣱ\nT;0;4:26:1:يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ\nT;0;4:26:2:مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمࣱ',
  '5;9;0;\nT;0;4:27:1:وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ\nT;0;4:27:2:ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمࣰا¦4:28:1:يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ\nT;0;4:28:2:عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفࣰا¦4:29:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nT;0;4:29:0:لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ\nT;0;4:29:0:تِجَٰرَةً عَن تَرَاضࣲ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ\nT;0;4:29:2:ٱللَّهَ كَانَ بِكُمۡ رَحِيمࣰا¦4:30:1:وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنࣰا\nT;0;4:30:0:وَظُلۡمࣰا فَسَوۡفَ نُصۡلِيهِ نَارࣰاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ\nT;0;4:30:2:يَسِيرًا¦4:31:1:إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ\nT;0;4:31:2:عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلࣰا كَرِيمࣰا\nT;0;4:32:1:وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضࣲۚ لِّلرِّجَالِ\nT;0;4:32:0:نَصِيبࣱ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبࣱ مِّمَّا ٱكۡتَسَبۡنَۚ\nT;0;4:32:0:وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ\nT;0;4:32:2:عَلِيمࣰا¦4:33:1:وَلِكُلࣲّ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ\nT;0;4:33:0:وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ\nT;0;4:33:2:نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدًا',
  '5;9;0;34\nT;0;4:34:1:ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ\nT;0;4:34:0:بَعۡضࣲ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ\nT;0;4:34:0:حَٰفِظَٰتࣱ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّٰتِي تَخَافُونَ\nT;0;4:34:0:نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ\nT;0;4:34:0:وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ\nT;0;4:34:2:إِنَّ ٱللَّهَ كَانَ عَلِيࣰّا كَبِيرࣰا¦4:35:1:وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا\nT;0;4:35:0:فَٱبۡعَثُواْ حَكَمࣰا مِّنۡ أَهۡلِهِۦ وَحَكَمࣰا مِّنۡ أَهۡلِهَآ إِن\nT;0;4:35:0:يُرِيدَآ إِصۡلَٰحࣰا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا\nT;0;4:35:2:خَبِيرࣰا¦4:36:1:۞ وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـࣰٔاۖ\nT;0;4:36:0:وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنࣰا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ\nT;0;4:36:0:وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ\nT;0;4:36:0:وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ\nT;0;4:36:2:لَا يُحِبُّ مَن كَانَ مُخۡتَالࣰا فَخُورًا¦4:37:1:ٱلَّذِينَ يَبۡخَلُونَ\nT;0;4:37:0:وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ\nT;0;4:37:2:ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابࣰا مُّهِينࣰا',
  '5;9;1;\nT;0;4:38:1:وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ بِٱللَّهِ\nT;0;4:38:0:وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينࣰا فَسَآءَ\nT;0;4:38:2:قَرِينࣰا¦4:39:1:وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُواْ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَنفَقُواْ\nT;0;4:39:2:مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِيمًا¦4:40:1:إِنَّ ٱللَّهَ لَا يَظۡلِمُ\nT;0;4:40:0:مِثۡقَالَ ذَرَّةࣲۖ وَإِن تَكُ حَسَنَةࣰ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ\nT;0;4:40:2:أَجۡرًا عَظِيمࣰا¦4:41:1:فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدࣲ\nT;0;4:41:2:وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدࣰا¦4:42:1:يَوۡمَئِذࣲ يَوَدُّ ٱلَّذِينَ\nT;0;4:42:0:كَفَرُواْ وَعَصَوُاْ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا يَكۡتُمُونَ\nT;0;4:42:2:ٱللَّهَ حَدِيثࣰا¦4:43:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ\nT;0;4:43:0:سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي\nT;0;4:43:0:سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ\nT;0;4:43:0:أَحَدࣱ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءࣰ\nT;0;4:43:0:فَتَيَمَّمُواْ صَعِيدࣰا طَيِّبࣰا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ\nT;0;4:43:2:إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا¦4:44:1:أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبࣰا مِّنَ\nT;0;4:44:2:ٱلۡكِتَٰبِ يَشۡتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ',
  '5;9;1;\nT;0;4:45:3:وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيࣰّا وَكَفَىٰ بِٱللَّهِ نَصِيرࣰا\nT;0;4:46:1:مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ\nT;0;4:46:0:سَمِعۡنَا وَعَصَيۡنَا وَٱسۡمَعۡ غَيۡرَ مُسۡمَعࣲ وَرَٰعِنَا لَيَّۢا بِأَلۡسِنَتِهِمۡ\nT;0;4:46:0:وَطَعۡنࣰا فِي ٱلدِّينِۚ وَلَوۡ أَنَّهُمۡ قَالُواْ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا\nT;0;4:46:0:لَكَانَ خَيۡرࣰا لَّهُمۡ وَأَقۡوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ\nT;0;4:46:2:إِلَّا قَلِيلࣰا¦4:47:1:يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا\nT;0;4:47:0:مُصَدِّقࣰا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهࣰا فَنَرُدَّهَا\nT;0;4:47:0:عَلَىٰٓ أَدۡبَارِهَآ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ\nT;0;4:47:2:ٱللَّهِ مَفۡعُولًا¦4:48:1:إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ\nT;0;4:48:2:ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا\nT;0;4:49:1:أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ\nT;0;4:49:2:وَلَا يُظۡلَمُونَ فَتِيلًا¦4:50:1:ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ\nT;0;4:50:2:وَكَفَىٰ بِهِۦٓ إِثۡمࣰا مُّبِينًا¦4:51:1:أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبࣰا\nT;0;4:51:0:مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ\nT;0;4:51:2:لِلَّذِينَ كَفَرُواْ هَٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا',
  '5;9;1;35\nT;0;4:52:3:أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ وَمَن يَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا\nT;0;4:53:3:أَمۡ لَهُمۡ نَصِيبࣱ مِّنَ ٱلۡمُلۡكِ فَإِذࣰا لَّا يُؤۡتُونَ ٱلنَّاسَ نَقِيرًا¦4:54:1:أَمۡ\nT;0;4:54:0:يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ\nT;0;4:54:2:ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمࣰا\nT;0;4:55:3:فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا\nT;0;4:56:1:إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارࣰا كُلَّمَا نَضِجَتۡ\nT;0;4:56:0:جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ\nT;0;4:56:2:عَزِيزًا حَكِيمࣰا¦4:57:1:وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ\nT;0;4:57:0:جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدࣰاۖ لَّهُمۡ فِيهَآ\nT;0;4:57:2:أَزۡوَٰجࣱ مُّطَهَّرَةࣱۖ وَنُدۡخِلُهُمۡ ظِلࣰّا ظَلِيلًا¦4:58:1:۞ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ\nT;0;4:58:0:أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن\nT;0;4:58:0:تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا\nT;0;4:58:2:بَصِيرࣰا¦4:59:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي\nT;0;4:59:0:ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءࣲ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ\nT;0;4:59:2:تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرࣱ وَأَحۡسَنُ تَأۡوِيلًا',
  '5;9;2;\nT;0;4:60:1:أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يَزۡعُمُونَ أَنَّهُمۡ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيۡكَ\nT;0;4:60:0:وَمَآ أُنزِلَ مِن قَبۡلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّٰغُوتِ\nT;0;4:60:0:وَقَدۡ أُمِرُوٓاْ أَن يَكۡفُرُواْ بِهِۦۖ وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ\nT;0;4:60:2:ضَلَٰلَۢا بَعِيدࣰا¦4:61:1:وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ\nT;0;4:61:0:ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيۡتَ ٱلۡمُنَٰفِقِينَ يَصُدُّونَ عَنكَ\nT;0;4:61:2:صُدُودࣰا¦4:62:1:فَكَيۡفَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةُۢ بِمَا\nT;0;4:62:0:قَدَّمَتۡ أَيۡدِيهِمۡ ثُمَّ جَآءُوكَ يَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَآ إِلَّآ\nT;0;4:62:2:إِحۡسَٰنࣰا وَتَوۡفِيقًا¦4:63:1:أُوْلَٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا\nT;0;4:63:0:فِي قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِيٓ\nT;0;4:63:2:أَنفُسِهِمۡ قَوۡلَۢا بَلِيغࣰا¦4:64:1:وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا\nT;0;4:64:0:لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوٓاْ أَنفُسَهُمۡ\nT;0;4:64:0:جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ\nT;0;4:64:2:لَوَجَدُواْ ٱللَّهَ تَوَّابࣰا رَّحِيمࣰا¦4:65:1:فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ\nT;0;4:65:0:حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ\nT;0;4:65:2:أَنفُسِهِمۡ حَرَجࣰا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمࣰا',
  '5;9;2;36\nT;0;4:66:1:وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن\nT;0;4:66:0:دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلࣱ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُواْ مَا يُوعَظُونَ\nT;0;4:66:2:بِهِۦ لَكَانَ خَيۡرࣰا لَّهُمۡ وَأَشَدَّ تَثۡبِيتࣰا¦4:67:1:وَإِذࣰا لَّأٓتَيۡنَٰهُم\nT;0;4:67:2:مِّن لَّدُنَّآ أَجۡرًا عَظِيمࣰا¦4:68:3:وَلَهَدَيۡنَٰهُمۡ صِرَٰطࣰا مُّسۡتَقِيمࣰا\nT;0;4:69:1:وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ\nT;0;4:69:0:عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَۚ\nT;0;4:69:2:وَحَسُنَ أُوْلَٰٓئِكَ رَفِيقࣰا¦4:70:1:ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ\nT;0;4:70:2:بِٱللَّهِ عَلِيمࣰا¦4:71:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ\nT;0;4:71:2:فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعࣰا¦4:72:1:وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ\nT;0;4:72:0:فَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةࣱ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن\nT;0;4:72:2:مَّعَهُمۡ شَهِيدࣰا¦4:73:1:وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلࣱ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن\nT;0;4:73:0:لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةࣱ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ\nT;0;4:73:2:فَأَفُوزَ فَوۡزًا عَظِيمࣰا¦4:74:1:۞ فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ\nT;0;4:74:0:يَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي سَبِيلِ\nT;0;4:74:2:ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمࣰا',
  '5;9;3;\nT;0;4:75:1:وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ\nT;0;4:75:0:وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ\nT;0;4:75:2:أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيࣰّا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا\nT;0;4:76:1:ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ يُقَٰتِلُونَ فِي\nT;0;4:76:0:سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ\nT;0;4:76:2:كَانَ ضَعِيفًا¦4:77:1:أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ\nT;0;4:77:0:ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقࣱ مِّنۡهُمۡ\nT;0;4:77:0:يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةࣰۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ\nT;0;4:77:0:عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلࣲ قَرِيبࣲۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلࣱ\nT;0;4:77:2:وَٱلۡأٓخِرَةُ خَيۡرࣱ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا¦4:78:1:أَيۡنَمَا تَكُونُواْ\nT;0;4:78:0:يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجࣲ مُّشَيَّدَةࣲۗ وَإِن تُصِبۡهُمۡ حَسَنَةࣱ\nT;0;4:78:0:يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةࣱ يَقُولُواْ هَٰذِهِۦ مِنۡ\nT;0;4:78:0:عِندِكَۚ قُلۡ كُلࣱّ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ\nT;0;4:78:2:حَدِيثࣰا¦4:79:1:مَّآ أَصَابَكَ مِنۡ حَسَنَةࣲ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةࣲ\nT;0;4:79:2:فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولࣰاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدࣰا',
  '5;9;3;\nT;0;4:80:1:مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ\nT;0;4:80:2:عَلَيۡهِمۡ حَفِيظࣰا¦4:81:1:وَيَقُولُونَ طَاعَةࣱ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ\nT;0;4:81:0:بَيَّتَ طَآئِفَةࣱ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ مَا يُبَيِّتُونَۖ\nT;0;4:81:2:فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا\nT;0;4:82:1:أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ\nT;0;4:82:2:لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفࣰا كَثِيرࣰا¦4:83:1:وَإِذَا جَآءَهُمۡ أَمۡرࣱ مِّنَ ٱلۡأَمۡنِ\nT;0;4:83:0:أَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ\nT;0;4:83:0:مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ\nT;0;4:83:2:عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلࣰا\nT;0;4:84:1:فَقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ\nT;0;4:84:0:عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ وَٱللَّهُ أَشَدُّ بَأۡسࣰا\nT;0;4:84:2:وَأَشَدُّ تَنكِيلࣰا¦4:85:1:مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةࣰ يَكُن لَّهُۥ\nT;0;4:85:0:نَصِيبࣱ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةࣰ سَيِّئَةࣰ يَكُن لَّهُۥ كِفۡلࣱ مِّنۡهَاۗ\nT;0;4:85:2:وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ مُّقِيتࣰا¦4:86:1:وَإِذَا حُيِّيتُم بِتَحِيَّةࣲ فَحَيُّواْ\nT;0;4:86:2:بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا',
  '5;9;3;37\nT;0;4:87:1:ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۗ\nT;0;4:87:2:وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثࣰا¦4:88:1:۞ فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ\nT;0;4:88:0:فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ\nT;0;4:88:2:أَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلࣰا¦4:89:1:وَدُّواْ لَوۡ تَكۡفُرُونَ\nT;0;4:89:0:كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءࣰۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ حَتَّىٰ\nT;0;4:89:0:يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ\nT;0;4:89:2:وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيࣰّا وَلَا نَصِيرًا¦4:90:1:إِلَّا ٱلَّذِينَ\nT;0;4:90:0:يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ حَصِرَتۡ\nT;0;4:90:0:صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ ٱللَّهُ\nT;0;4:90:0:لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ\nT;0;4:90:2:وَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلࣰا\nT;0;4:91:1:سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ مَا\nT;0;4:91:0:رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ\nT;0;4:91:0:إِلَيۡكُمُ ٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ\nT;0;4:91:2:ثَقِفۡتُمُوهُمۡۚ وَأُوْلَٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنࣰا مُّبِينࣰا',
  '5;10;0;\nT;0;4:92:1:وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـࣰٔاۚ وَمَن قَتَلَ\nT;0;4:92:0:مُؤۡمِنًا خَطَـࣰٔا فَتَحۡرِيرُ رَقَبَةࣲ مُّؤۡمِنَةࣲ وَدِيَةࣱ مُّسَلَّمَةٌ\nT;0;4:92:0:إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوࣲّ\nT;0;4:92:0:لَّكُمۡ وَهُوَ مُؤۡمِنࣱ فَتَحۡرِيرُ رَقَبَةࣲ مُّؤۡمِنَةࣲۖ وَإِن كَانَ\nT;0;4:92:0:مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقࣱ فَدِيَةࣱ مُّسَلَّمَةٌ إِلَىٰٓ\nT;0;4:92:0:أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةࣲ مُّؤۡمِنَةࣲۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ\nT;0;4:92:0:شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةࣰ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ\nT;0;4:92:2:عَلِيمًا حَكِيمࣰا¦4:93:1:وَمَن يَقۡتُلۡ مُؤۡمِنࣰا مُّتَعَمِّدࣰا\nT;0;4:93:0:فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدࣰا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ\nT;0;4:93:2:وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمࣰا¦4:94:1:يَٰٓأَيُّهَا ٱلَّذِينَ\nT;0;4:94:0:ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ\nT;0;4:94:0:لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنࣰا تَبۡتَغُونَ\nT;0;4:94:0:عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةࣱۚ\nT;0;4:94:0:كَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ\nT;0;4:94:2:فَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرࣰا',
  '5;10;0;38\nT;0;4:95:1:لَّا يَسۡتَوِي ٱلۡقَٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِينَ غَيۡرُ أُوْلِي ٱلضَّرَرِ وَٱلۡمُجَٰهِدُونَ\nT;0;4:95:0:فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ بِأَمۡوَٰلِهِمۡ\nT;0;4:95:0:وَأَنفُسِهِمۡ عَلَى ٱلۡقَٰعِدِينَ دَرَجَةࣰۚ وَكُلࣰّا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ\nT;0;4:95:2:ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمࣰا¦4:96:1:دَرَجَٰتࣲ مِّنۡهُ وَمَغۡفِرَةࣰ\nT;0;4:96:2:وَرَحۡمَةࣰۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِيمًا¦4:97:1:إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ\nT;0;4:97:0:ظَالِمِيٓ أَنفُسِهِمۡ قَالُواْ فِيمَ كُنتُمۡۖ قَالُواْ كُنَّا مُسۡتَضۡعَفِينَ فِي ٱلۡأَرۡضِۚ\nT;0;4:97:0:قَالُوٓاْ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَٰسِعَةࣰ فَتُهَاجِرُواْ فِيهَاۚ فَأُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ\nT;0;4:97:2:جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا¦4:98:1:إِلَّا ٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ\nT;0;4:98:2:وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ لَا يَسۡتَطِيعُونَ حِيلَةࣰ وَلَا يَهۡتَدُونَ سَبِيلࣰا\nT;0;4:99:3:فَأُوْلَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورࣰا¦4:100:1:۞ وَمَن\nT;0;4:100:0:يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمࣰا كَثِيرࣰا وَسَعَةࣰۚ وَمَن\nT;0;4:100:0:يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ\nT;0;4:100:2:وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِيمࣰا¦4:101:1:وَإِذَا ضَرَبۡتُمۡ فِي\nT;0;4:101:0:ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ\nT;0;4:101:2:أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوࣰّا مُّبِينࣰا',
  '5;10;1;\nT;0;4:102:1:وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةࣱ\nT;0;4:102:0:مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ\nT;0;4:102:0:مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ\nT;0;4:102:0:مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ\nT;0;4:102:0:كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ\nT;0;4:102:0:عَلَيۡكُم مَّيۡلَةࣰ وَٰحِدَةࣰۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ\nT;0;4:102:0:أَذࣰى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ\nT;0;4:102:2:وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابࣰا مُّهِينࣰا\nT;0;4:103:1:فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمࣰا وَقُعُودࣰا وَعَلَىٰ\nT;0;4:103:0:جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ\nT;0;4:103:2:كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبࣰا مَّوۡقُوتࣰا¦4:104:1:وَلَا تَهِنُواْ فِي\nT;0;4:104:0:ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا\nT;0;4:104:0:تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ\nT;0;4:104:2:عَلِيمًا حَكِيمًا¦4:105:1:إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ\nT;0;4:105:2:بَيۡنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمࣰا',
  '5;10;1;\nT;0;4:106:3:وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِيمࣰا¦4:107:1:وَلَا تُجَٰدِلۡ\nT;0;4:107:0:عَنِ ٱلَّذِينَ يَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ\nT;0;4:107:2:خَوَّانًا أَثِيمࣰا¦4:108:1:يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ\nT;0;4:108:0:مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ\nT;0;4:108:2:وَكَانَ ٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا¦4:109:1:هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ\nT;0;4:109:0:جَٰدَلۡتُمۡ عَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ\nT;0;4:109:2:يَوۡمَ ٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلࣰا¦4:110:1:وَمَن يَعۡمَلۡ\nT;0;4:110:0:سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورࣰا\nT;0;4:110:2:رَّحِيمࣰا¦4:111:1:وَمَن يَكۡسِبۡ إِثۡمࣰا فَإِنَّمَا يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ\nT;0;4:111:2:وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمࣰا¦4:112:1:وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمࣰا\nT;0;4:112:2:ثُمَّ يَرۡمِ بِهِۦ بَرِيٓـࣰٔا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنࣰا وَإِثۡمࣰا مُّبِينࣰا\nT;0;4:113:1:وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةࣱ مِّنۡهُمۡ\nT;0;4:113:0:أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ\nT;0;4:113:0:مِن شَيۡءࣲۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ\nT;0;4:113:2:مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمࣰا',
  '5;10;2;39\nT;0;4:114:1:۞ لَّا خَيۡرَ فِي كَثِيرࣲ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ\nT;0;4:114:0:أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ\nT;0;4:114:2:ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمࣰا¦4:115:1:وَمَن\nT;0;4:115:0:يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ\nT;0;4:115:0:سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ\nT;0;4:115:2:مَصِيرًا¦4:116:1:إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ\nT;0;4:116:0:ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا\nT;0;4:116:2:بَعِيدًا¦4:117:1:إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثࣰا وَإِن يَدۡعُونَ\nT;0;4:117:2:إِلَّا شَيۡطَٰنࣰا مَّرِيدࣰا¦4:118:1:لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ\nT;0;4:118:2:عِبَادِكَ نَصِيبࣰا مَّفۡرُوضࣰا¦4:119:1:وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ\nT;0;4:119:0:وَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ\nT;0;4:119:0:فَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيࣰّا مِّن\nT;0;4:119:2:دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانࣰا مُّبِينࣰا¦4:120:1:يَعِدُهُمۡ\nT;0;4:120:2:وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا¦4:121:1:أُوْلَٰٓئِكَ\nT;0;4:121:2:مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصࣰا',
  '5;10;2;\nT;0;4:122:1:وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّٰتࣲ\nT;0;4:122:0:تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدࣰاۖ وَعۡدَ ٱللَّهِ\nT;0;4:122:2:حَقࣰّاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلࣰا¦4:123:1:لَّيۡسَ بِأَمَانِيِّكُمۡ\nT;0;4:123:0:وَلَآ أَمَانِيِّ أَهۡلِ ٱلۡكِتَٰبِۗ مَن يَعۡمَلۡ سُوٓءࣰا يُجۡزَ بِهِۦ\nT;0;4:123:2:وَلَا يَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيࣰّا وَلَا نَصِيرࣰا¦4:124:1:وَمَن\nT;0;4:124:0:يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ\nT;0;4:124:2:فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ نَقِيرࣰا¦4:125:1:وَمَنۡ\nT;0;4:125:0:أَحۡسَنُ دِينࣰا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنࣱ وَٱتَّبَعَ\nT;0;4:125:2:مِلَّةَ إِبۡرَٰهِيمَ حَنِيفࣰاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلࣰا¦4:126:1:وَلِلَّهِ\nT;0;4:126:0:مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءࣲ\nT;0;4:126:2:مُّحِيطࣰا¦4:127:1:وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ\nT;0;4:127:0:فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ\nT;0;4:127:0:ٱلَّٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ\nT;0;4:127:0:وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ بِٱلۡقِسۡطِۚ\nT;0;4:127:2:وَمَا تَفۡعَلُواْ مِنۡ خَيۡرࣲ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمࣰا',
  '5;10;2;\nT;0;4:128:1:وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضࣰا فَلَا جُنَاحَ\nT;0;4:128:0:عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحࣰاۚ وَٱلصُّلۡحُ خَيۡرࣱۗ\nT;0;4:128:0:وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ\nT;0;4:128:2:كَانَ بِمَا تَعۡمَلُونَ خَبِيرࣰا¦4:129:1:وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ\nT;0;4:129:0:بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا\nT;0;4:129:0:كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ\nT;0;4:129:2:غَفُورࣰا رَّحِيمࣰا¦4:130:1:وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلࣰّا مِّن سَعَتِهِۦۚ\nT;0;4:130:2:وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمࣰا¦4:131:1:وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ\nT;0;4:131:0:وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن\nT;0;4:131:0:قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ\nT;0;4:131:2:مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدࣰا\nT;0;4:132:3:وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا\nT;0;4:133:1:إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ\nT;0;4:133:2:ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرࣰا¦4:134:1:مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ\nT;0;4:134:2:ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرࣰا',
  '5;10;3;40\nT;0;4:135:1:۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ\nT;0;4:135:0:عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرࣰا\nT;0;4:135:0:فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ\nT;0;4:135:2:أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرࣰا¦4:136:1:يَٰٓأَيُّهَا\nT;0;4:136:0:ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ\nT;0;4:136:0:عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ\nT;0;4:136:0:بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ\nT;0;4:136:2:ضَلَٰلَۢا بَعِيدًا¦4:137:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ\nT;0;4:137:0:كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرࣰا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ\nT;0;4:137:2:سَبِيلَۢا¦4:138:3:بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا¦4:139:1:ٱلَّذِينَ\nT;0;4:139:0:يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ\nT;0;4:139:2:عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعࣰا¦4:140:1:وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي\nT;0;4:140:0:ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا\nT;0;4:140:0:تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذࣰا مِّثۡلُهُمۡۗ\nT;0;4:140:2:إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا',
  '5;10;3;\nT;0;4:141:1:ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحࣱ مِّنَ ٱللَّهِ قَالُوٓاْ\nT;0;4:141:0:أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبࣱ قَالُوٓاْ\nT;0;4:141:0:أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ\nT;0;4:141:0:بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ\nT;0;4:141:2:سَبِيلًا¦4:142:1:إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا\nT;0;4:142:0:قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ\nT;0;4:142:2:ٱللَّهَ إِلَّا قَلِيلࣰا¦4:143:1:مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ\nT;0;4:143:2:هَٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلࣰا¦4:144:1:يَٰٓأَيُّهَا ٱلَّذِينَ\nT;0;4:144:0:ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ\nT;0;4:144:2:أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنࣰا مُّبِينًا¦4:145:1:إِنَّ\nT;0;4:145:2:ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا\nT;0;4:146:1:إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ\nT;0;4:146:0:دِينَهُمۡ لِلَّهِ فَأُوْلَٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ\nT;0;4:146:2:ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمࣰا¦4:147:1:مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ\nT;0;4:147:2:إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمࣰا',
];
